her":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"Wex: grievance","document_date":null},"retrieved_at":"2026-10-12T07:06:18Z","content_sha256":"e342533040d64c8cbd8026a93163823f0bb1b9335d213da763466e14a1386af7","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"ma-150e-s5","provenance":{"provenance_id":"prov-5d64654e761bfb15c43bfcf7ffeb6e3656d3b2772f6329d25d10f8062b3d809e","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section5","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 5","document_date":null},"retrieved_at":"2026-10-12T07:04:36Z","content_sha256":"fdb248746b5c1acc6457f4d7f536ff00a6dd0bf3d5d9b7236f1b1e0e4f41ef78","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"ma-150e-s1","provenance":{"provenance_id":"prov-946c243f5c2e016d2c7cca739060f56da00c7fdffa96b123a14c06623d3d9461","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section1","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 1","document_date":null},"retrieved_at":"2026-10-12T07:04:30Z","content_sha256":"f627eeb678daa6ec888fde9e8a968fbbbe17103a17d0ebfed7741f3453a9247c","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"547e2a8f-9abd-53e7-a5a0-bda906b4db40","payload":{"kind":"mini_lesson","locale":"en","locale_state":"reviewed","title":"What is a bargaining unit, and am I in one?","body":"A bargaining unit is the group of jobs a union represents as the exclusive bargaining representative. The Massachusetts Department of Labor Relations (DLR) explains that the contract defines which positions or job classifications are in the unit. Being in the unit is not the same as being a union member: members are people in the unit who choose to join. The DLR and the Commonwealth Employment Relations Board (CERB) decide which units are appropriate, looking at things like community of interest. To learn whether your job is in a unit, check your contract or ask your steward.","attribution":"","source":"Massachusetts Department of Labor Relations (mass.gov), FAQ - Representation Rights, retrieved Oct 12, 2026 (https://www.mass.gov/info-details/faq-representation-rights); Massachusetts Department of Labor Relations (mass.gov), DLR Q&A re: Janus v. AFSCME, retrieved Oct 12, 2026 (https://www.mass.gov/info-details/dlr-qa-re-janus-v-american-fed-of-state-cty-muni-employees)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"d