ghts","document_date":null},"retrieved_at":"2026-10-12T07:09:54Z","content_sha256":"5b7f0e2d074c235d2c48e6f2c938ce7ae62300329419c9955b671ed35f9e8492","capture":{"method":"firecrawl"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"dlr-janus-qa","provenance":{"provenance_id":"prov-c903fcab77e757f1559444092413acbfe9fc207cd2e13125b166275e66d3debc","source":{"url":"https://www.mass.gov/info-details/dlr-qa-re-janus-v-american-fed-of-state-cty-muni-employees","publisher":"Massachusetts Department of Labor Relations (mass.gov)","title":"DLR Q&A re: Janus v. AFSCME","document_date":null},"retrieved_at":"2026-10-12T07:09:24Z","content_sha256":"be82dac0fc704fa097700b92f1fe4f77ac9a8dc2af1ef8470b0d8dc14376d3c8","capture":{"method":"firecrawl"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"9863f625-5f84-52a2-a300-276858e40fb2","payload":{"kind":"mini_lesson","locale":"es","locale_state":"reviewed","title":"¿Qué es una unidad de negociación y formo parte de una?","body":"Una unidad de negociación (bargaining unit) es el grupo de puestos que un sindicato representa como representante exclusivo. El Departamento de Relaciones Laborales de Massachusetts (Department of Labor Relations, DLR) explica que el convenio colectivo (contrato) define qué puestos o clasificaciones forman parte de la unidad. Estar en la unidad no es lo mismo que ser miembro del sindicato: los miembros son las personas de la unidad que deciden afiliarse. El DLR y la Junta de Relaciones Laborales del Estado (Commonwealth Employment Relations Board, CERB) deciden qué unidades son apropiadas, según criterios como los intereses en común. Para saber si su puesto está en una unidad, revise su contrato o pregunte a su delegado o delegada sindical.","attribution":"","source":"Massachusetts Department of Labor Relations (mass.gov), FAQ - Representation Rights, consultada el 12 oct 2026 (https://www.mass.gov/info-details/faq-representation-rights); Massachusetts Department of Labor Relations (mass.gov), DLR Q&A re: Janus v. AFSCME, consultada el 12 oct 2026 (https://www.mass.gov/info-details/dlr-qa-re-janus-v-american-fed-of-state-cty-muni-employees)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","membership"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-what-is-a-bargaining-unit","locale":"es","record":{"provenance_id":"prov-539dad062a89f9afeaf32e2cd11f5a91f7b93621f712d03f398956ace8df124e","source":{"url":"https://app.example.invalid/#faq-what-is-a-bargaining-unit","publisher":"Union Ground platform content (authored draft)","title":"What is a bargaining unit, and am I in one?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"6388c08aee81a386512ba18deceb5f3573b32650f7bb46bb9663126a0d8dd5b2","capture":{"