tractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"ma-150e-s5a","provenance":{"provenance_id":"prov-26ecba5c6cbc9ab17124be4fa65f69f9729091fb7a55b2df07dddb222a07b830","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section5A","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 5A","document_date":null},"retrieved_at":"2026-10-12T07:04:37Z","content_sha256":"3c86eead1a3985b3a257bfbedc1f1ca991f61f5637dd5e6c137ddae0bef13c36","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"usc-29-431","provenance":{"provenance_id":"prov-c7bfdf0c8b0ca70089e10fd447440bd95248d9e18bebf53e00f3ef20d903f99f","source":{"url":"https://www.law.cornell.edu/uscode/text/29/431","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"29 U.S. Code 431 - Report of labor organizations","document_date":null},"retrieved_at":"2026-10-12T07:05:57Z","content_sha256":"fbbc5d6b424aac107445ef5fed5e792fd59f0e2b96b3b87f0063b696b1af5228","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"92c4728f-a096-5709-a024-01b9044732ed","payload":{"kind":"mini_lesson","locale":"en","locale_state":"reviewed","title":"How do I find my steward?","body":"Ask a coworker in your unit or contact your union's office. In Massachusetts public employment, your employer must let the union meet with each new hire for at least 30 minutes, no later than 10 calendar days after the date of hire, often during new employee orientation. The union may also use the employer's email system to reach unit members about union matters. If your union files reports with the U.S. Department of Labor's Office of Labor-Management Standards (OLMS), you can find its constitution and bylaws in the OLMS Online Public Disclosure Room. Once you know your steward, save their contact details.","attribution":"","source":"U.S. Department of Labor, Office of Labor-Management Standards (dol.gov), OLMS Online Public Disclosure Room, retrieved Oct 12, 2026 (https://www.dol.gov/agencies/olms/public-disclosure-room); Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 5A, retrieved Oct 12, 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section5A)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","membership"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-how-do-i-find-my-steward","locale":"en","record":{"prove