tring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"ma-150e-s5a","provenance":{"provenance_id":"prov-26ecba5c6cbc9ab17124be4fa65f69f9729091fb7a55b2df07dddb222a07b830","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section5A","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 5A","document_date":null},"retrieved_at":"2026-10-12T07:04:37Z","content_sha256":"3c86eead1a3985b3a257bfbedc1f1ca991f61f5637dd5e6c137ddae0bef13c36","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"bca64343-c141-5f0f-ad41-a32a66ed5900","payload":{"kind":"mini_lesson","locale":"es","locale_state":"reviewed","title":"¿Cómo encuentro a mi delegado o delegada sindical?","body":"Pregunte a un compañero de su unidad o comuníquese con la oficina de su sindicato. En el empleo público de Massachusetts, su empleador debe permitir que el sindicato se reúna con cada persona recién contratada por al menos 30 minutos, a más tardar 10 días calendario después de la fecha de contratación, a menudo durante la orientación de nuevos empleados. El sindicato también puede usar el sistema de correo electrónico del empleador para comunicarse con la unidad sobre asuntos sindicales. Si su sindicato presenta informes ante la Oficina de Normas Laborales-Gerenciales (Office of Labor-Management Standards, OLMS) del Departamento de Trabajo de EE. UU., puede encontrar sus estatutos en la Sala de Divulgación Pública en línea de la OLMS. Cuando sepa quién es su delegado o delegada sindical, guarde sus datos de contacto.","attribution":"","source":"U.S. Department of Labor, Office of Labor-Management Standards (dol.gov), OLMS Online Public Disclosure Room, consultada el 12 oct 2026 (https://www.dol.gov/agencies/olms/public-disclosure-room); Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 5A, consultada el 12 oct 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section5A)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","membership"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-how-do-i-find-my-steward","locale":"es","record":{"provenance_id":"prov-4a31d170b114981ffd631f65edbb63f78341922d3f4686377b056535b66349c3","source":{"url":"https://app.example.invalid/#faq-how-do-i-find-my-steward","publisher":"Union Ground platform content (authored draft)","title":"How do I find my steward?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"d1e66bcf8024c4a5352a4d4640e850308907d124609420d743251f10dd878629","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-e137149bcb356d90f11b97116b55a2665e46357345e9b01e3e737449045ca86d","prov-26ecba5c6cbc9ab17124be4fa65f69f9729091fb7a55b2df07dddb222a07b830"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"olms-disclosure","provenance":{"provenance_id":"prov-e137149bcb356d90f11b97116b55a2665e46357345e9b01e3e737449045ca86d","source":{"url":"https://www.dol.gov/agencies/olms/public-disclosure-room","publisher":"U.S. Department of Labor, Office of Labor-Management Standards (dol.gov)","title":"OLMS Online Public Disclosure Room","document_date":null},"retrieved_at":"2026-10-12T07:06:30Z","content_sha256":"d18858e69a7643a3cb7f1e74af2bb27b56e07dc08f545ead3fe973b7314c1936","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"ma-150e-s5a","provenance":{"provenance_id":"prov-26ecba5c6cbc9ab17124be4fa65f69f9729091fb7a55b2df07dddb222a07b830","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section5A","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 5A","document_date":null},"retrieved_at":"2026-10-12T07:04:37Z","content_sha256":"3c86eead1a3985b3a257bfbedc1f1ca991f61f5637dd5e6c137ddae0bef13c36","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"e01fd05f-4036-5362-a7b6-dab2cda385ad","payload":{"kind":"mini_lesson","locale":"en","locale_state":"reviewed","title":"Do I have to join the union?","body":"No. In Massachusetts public employment, c. 150E gives you the right to form, join or assist a union, and also the right to refrain. Since the U.S. Supreme Court decided Janus v. AFSCME in 2018, the Massachusetts Department of Labor Relations (DLR) says it is unlawful for public employers or unions to require a nonmember to pay an agency fee as a condition of getting or keeping a job. If you choose to be a member, the DLR notes that most, if not all, unions require membership dues. Private-sector rules are different. For your own situation, ask your steward.","attribution":"","source":"Massachusetts Department of Labor Relations (mass.gov), DLR Q&A re: Janus v. AFSCME, retrieved Oct 12, 2026 (https://www.mass.gov/info-details/dlr-qa-re-janus-v-american-fed-of-state-cty-muni-employees); Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 2, retrieved Oct 12, 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section2)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","membership"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-do-i-have-to-join-the-union","locale":"en","record":{"provenance_id":"prov-1bd58c74df0bf9441de7310684e22a5b2e430f457e02415faa5dd4cdc0237e7b","source":{"url":"https://app.example.invalid/#faq-do-i-have-to-join-the-union","publisher":"Union Ground platform content (authored draft)","title":"Do I have to join the union?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"7277088206f49419f5a4a7cdace90b4ea6b58597a2fe9410f34df37ba2b0bcd7","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-c903fcab77e757f1559444092413acbfe9fc207cd2e13125b166275e66d3debc","prov-126932b67a9f47b18d5e6fbf72e8e8f9d02d5bd1e8c15f9323576ecb22e2fbce"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"dlr-janus-qa","provenance":{"provenance_id":"prov-c903fcab77e757f1559444092413acbfe9fc207cd2e13125b166275e66d3debc","source":{"url":"https://www.mass.gov/info-details/dlr-qa-re-janus-v-american-fed-of-state-cty-muni-employees","publisher":"Massachusetts Department of Labor Relations (mass.gov)","title":"DLR Q&A re: Janus v. AFSCME","document_date":null},"retrieved_at":"2026-10-12T07:09:24Z","content_sha256":"be82dac0fc704fa097700b92f1fe4f77ac9a8dc2af1ef8470b0d8dc14376d3c8","capture":{"method":"firecrawl"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"ma-150e-s2","provenance":{"provenance_id":"prov-126932b67a9f47b18d5e6fbf72e8e8f9d02d5bd1e8c15f9323576ecb22e2fbce","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section2","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 2","document_date":null},"retrieved_at":"2026-10-12T07:04:32Z","content_sha256":"0ebbd12fb8b21954f920a48d5eb9c06c655996c8305010873f260f821aac1207","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"b5f0c6f2-f1c7-59e8-aed2-b5f666517af0","payload":{"kind":"mini_lesson","locale":"es","locale_state":"reviewed","title":"¿Estoy obligado a afiliarme al sindicato?","body":"No. En el empleo público de Massachusetts, la ley c. 150E le da el derecho de formar un sindicato, afiliarse o ayudarlo, y también el derecho de no hacerlo. Desde que la Corte Suprema de EE. UU. decidió el caso Janus v. AFSCME en 2018, el Departamento de Relaciones Laborales de Massachusetts (DLR) dice que es ilegal que los empleadores públicos o los sindicatos exijan a una persona no afiliada pagar una cuota de agencia (agency fee) como condición para obtener o conservar el empleo. Si usted decide afiliarse, el DLR señala que la mayoría de los sindicatos, si no todos, exigen cuotas sindicales (dues). Las reglas del sector privado son distintas. Para su situación personal, pregunte a su delegado o delegada sindical.","attribution":"","source":"Massachusetts Department of Labor Relations (mass.gov), DLR Q&A re: Janus v. AFSCME, consultada el 12 oct 2026 (https://www.mass.gov/info-details/dlr-qa-re-janus-v-american-fed-of-state-cty-muni-employees); Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 2, consultada el 12 oct 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section2)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","membership"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-do-i-have-to-join-the-union","locale":"es","record":{"provenance_id":"prov-1bd58c74df0bf9441de7310684e22a5b2e430f457e02415faa5dd4cdc0237e7b","source":{"url":"https://app.example.invalid/#faq-do-i-have-to-join-the-union","publisher":"Union Ground platform content (authored draft)","title":"Do I have to join the union?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"7277088206f49419f5a4a7cdace90b4ea6b58597a2fe9410f34df37ba2b0bcd7","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-c903fcab77e757f1559444092413acbfe9fc207cd2e13125b166275e66d3debc","prov-126932b67a9f47b18d5e6fbf72e8e8f9d02d5bd1e8c15f9323576ecb22e2fbce"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"dlr-janus-qa","provenance":{"provenance_id":"prov-c903fcab77e757f1559444092413acbfe9fc207cd2e13125b166275e66d3debc","source":{"url":"https://www.mass.gov/info-details/dlr-qa-re-janus-v-american-fed-of-state-cty-muni-employees","publisher":"Massachusetts Department of Labor Relations (mass.gov)","title":"DLR Q&A re: Janus v. AFSCME","document_date":null},"retrieved_at":"2026-10-12T07:09:24Z","content_sha256":"be82dac0fc704fa097700b92f1fe4f77ac9a8dc2af1ef8470b0d8dc14376d3c8","capture":{"method":"firecrawl"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"ma-150e-s2","provenance":{"provenance_id":"prov-126932b67a9f47b18d5e6fbf72e8e8f9d02d5bd1e8c15f9323576ecb22e2fbce","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section2","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 2","document_date":null},"retrieved_at":"2026-10-12T07:04:32Z","content_sha256":"0ebbd12fb8b21954f920a48d5eb9c06c655996c8305010873f260f821aac1207","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"5a5d37a5-340f-53f3-a429-da0cb14748ff","payload":{"kind":"mini_lesson","locale":"en","locale_state":"reviewed","title":"If I don't join the union, does the contract still cover me?","body":"Yes. The Massachusetts Department of Labor Relations (DLR) says that under c. 150E, s. 5, the terms of the contract apply to everyone in the bargaining unit, whether or not they join the union. The union, as exclusive representative, must represent all employees in the unit without discrimination and without regard to membership. There is one limit: the law lets the union require a nonmember to pay the reasonable costs and fees of a grievance or arbitration brought at the nonmember's request, including arbitrator fees and related attorney fees. Ask your steward how this works in your unit.","attribution":"","source":"Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 5, retrieved Oct 12, 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section5); Massachusetts Department of Labor Relations (mass.gov), DLR Q&A re: Janus v. AFSCME, retrieved Oct 12, 2026 (https://www.mass.gov/info-details/dlr-qa-re-janus-v-american-fed-of-state-cty-muni-employees)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","membership"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-does-the-contract-cover-nonmembers","locale":"en","record":{"provenance_id":"prov-c944e5700875c38de81c1b1e3b8dfc9a6dce67b672ae9da600baeb8917130357","source":{"url":"https://app.example.invalid/#faq-does-the-contract-cover-nonmembers","publisher":"Union Ground platform content (authored draft)","title":"If I don't join the union, does the contract still cover me?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"a788fa21313349637d49177e7807c9a040415b3b815c09cce5227e57233b361f","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-5d64654e761bfb15c43bfcf7ffeb6e3656d3b2772f6329d25d10f8062b3d809e","prov-c903fcab77e757f1559444092413acbfe9fc207cd2e13125b166275e66d3debc"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"ma-150e-s5","provenance":{"provenance_id":"prov-5d64654e761bfb15c43bfcf7ffeb6e3656d3b2772f6329d25d10f8062b3d809e","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section5","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 5","document_date":null},"retrieved_at":"2026-10-12T07:04:36Z","content_sha256":"fdb248746b5c1acc6457f4d7f536ff00a6dd0bf3d5d9b7236f1b1e0e4f41ef78","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"dlr-janus-qa","provenance":{"provenance_id":"prov-c903fcab77e757f1559444092413acbfe9fc207cd2e13125b166275e66d3debc","source":{"url":"https://www.mass.gov/info-details/dlr-qa-re-janus-v-american-fed-of-state-cty-muni-employees","publisher":"Massachusetts Department of Labor Relations (mass.gov)","title":"DLR Q&A re: Janus v. AFSCME","document_date":null},"retrieved_at":"2026-10-12T07:09:24Z","content_sha256":"be82dac0fc704fa097700b92f1fe4f77ac9a8dc2af1ef8470b0d8dc14376d3c8","capture":{"method":"firecrawl"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"e05883af-5c01-54a1-a9a2-749f7ddc5464","payload":{"kind":"mini_lesson","locale":"es","locale_state":"reviewed","title":"Si no me afilio al sindicato, ¿el contrato me sigue cubriendo?","body":"Sí. El Departamento de Relaciones Laborales de Massachusetts (DLR) dice que, según la ley c. 150E, sección 5, los términos del convenio colectivo (contrato) se aplican a todas las personas de la unidad de negociación, se afilien o no al sindicato. El sindicato, como representante exclusivo, debe representar a todos los empleados de la unidad sin discriminación y sin importar si son miembros. Hay un límite: la ley permite que el sindicato le cobre a una persona no afiliada los costos y honorarios razonables de una queja formal (grievance) o un arbitraje que se presente a pedido de esa persona, incluidos los honorarios del árbitro y de abogados relacionados. Pregunte a su delegado o delegada sindical cómo funciona esto en su unidad.","attribution":"","source":"Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 5, consultada el 12 oct 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section5); Massachusetts Department of Labor Relations (mass.gov), DLR Q&A re: Janus v. AFSCME, consultada el 12 oct 2026 (https://www.mass.gov/info-details/dlr-qa-re-janus-v-american-fed-of-state-cty-muni-employees)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","membership"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-does-the-contract-cover-nonmembers","locale":"es","record":{"provenance_id":"prov-c944e5700875c38de81c1b1e3b8dfc9a6dce67b672ae9da600baeb8917130357","source":{"url":"https://app.example.invalid/#faq-does-the-contract-cover-nonmembers","publisher":"Union Ground platform content (authored draft)","title":"If I don't join the union, does the contract still cover me?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"a788fa21313349637d49177e7807c9a040415b3b815c09cce5227e57233b361f","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-5d64654e761bfb15c43bfcf7ffeb6e3656d3b2772f6329d25d10f8062b3d809e","prov-c903fcab77e757f1559444092413acbfe9fc207cd2e13125b166275e66d3debc"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"ma-150e-s5","provenance":{"provenance_id":"prov-5d64654e761bfb15c43bfcf7ffeb6e3656d3b2772f6329d25d10f8062b3d809e","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section5","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 5","document_date":null},"retrieved_at":"2026-10-12T07:04:36Z","content_sha256":"fdb248746b5c1acc6457f4d7f536ff00a6dd0bf3d5d9b7236f1b1e0e4f41ef78","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"dlr-janus-qa","provenance":{"provenance_id":"prov-c903fcab77e757f1559444092413acbfe9fc207cd2e13125b166275e66d3debc","source":{"url":"https://www.mass.gov/info-details/dlr-qa-re-janus-v-american-fed-of-state-cty-muni-employees","publisher":"Massachusetts Department of Labor Relations (mass.gov)","title":"DLR Q&A re: Janus v. AFSCME","document_date":null},"retrieved_at":"2026-10-12T07:09:24Z","content_sha256":"be82dac0fc704fa097700b92f1fe4f77ac9a8dc2af1ef8470b0d8dc14376d3c8","capture":{"method":"firecrawl"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"b1290f17-281a-5804-a2fc-85df09b5fc08","payload":{"kind":"mini_lesson","locale":"en","locale_state":"reviewed","title":"Who decides what my union asks for in bargaining?","body":"In Massachusetts public employment, the union that is the exclusive representative bargains with the employer over wages, hours, standards of productivity and performance, and other terms and conditions of employment. Each side may choose who represents it at the bargaining table. How the union sets its demands is decided by its own constitution and bylaws. Unions covered by federal reporting law must file a statement with the U.S. Department of Labor describing how bargaining demands are authorized and how contract terms are ratified. Federal law also gives members of those unions the right to attend membership meetings and take part in the discussion and voting.","attribution":"","source":"Massachusetts Department of Labor Relations (mass.gov), FAQ - The Collective Bargaining Process, retrieved Oct 12, 2026 (https://www.mass.gov/info-details/faq-the-collective-bargaining-process); Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 6, retrieved Oct 12, 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section6); Legal Information Institute, Cornell Law School (law.cornell.edu), 29 U.S. Code 411 - Bill of rights; constitution and bylaws of labor organizations, retrieved Oct 12, 2026 (https://www.law.cornell.edu/uscode/text/29/411); Legal Information Institute, Cornell Law School (law.cornell.edu), 29 U.S. Code 431 - Report of labor organizations, retrieved Oct 12, 2026 (https://www.law.cornell.edu/uscode/text/29/431)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","membership"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-who-decides-what-the-union-negotiates","locale":"en","record":{"provenance_id":"prov-69853fad086bff8efcae0447edded48dcb93f71dfa30715b8d6f8c0f442c6332","source":{"url":"https://app.example.invalid/#faq-who-decides-what-the-union-negotiates","publisher":"Union Ground platform content (authored draft)","title":"Who decides what my union asks for in bargaining?","document_date":"2026-10-12"},"ret