.gov)","title":"M.G.L. c. 150E, section 6","document_date":null},"retrieved_at":"2026-10-12T07:04:38Z","content_sha256":"4dccd774006ead9f4b85112c6d01ea8bb46e3c162d1db0ebd799c096b5fa0e54","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"usc-29-411","provenance":{"provenance_id":"prov-1b9c459692a115193a6b908ee3697b0688a17441c3091f34b1518e4be7ea1d9b","source":{"url":"https://www.law.cornell.edu/uscode/text/29/411","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"29 U.S. Code 411 - Bill of rights; constitution and bylaws of labor organizations","document_date":null},"retrieved_at":"2026-10-12T07:05:58Z","content_sha256":"a4bad78c1e6e0fac5ed46e8a7e927e4aa0244bea5d6bf9029fe03fe66a21cd42","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"usc-29-431","provenance":{"provenance_id":"prov-c7bfdf0c8b0ca70089e10fd447440bd95248d9e18bebf53e00f3ef20d903f99f","source":{"url":"https://www.law.cornell.edu/uscode/text/29/431","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"29 U.S. Code 431 - Report of labor organizations","document_date":null},"retrieved_at":"2026-10-12T07:05:57Z","content_sha256":"fbbc5d6b424aac107445ef5fed5e792fd59f0e2b96b3b87f0063b696b1af5228","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"0f29cbba-d02c-537f-a293-e6a4117e18ae","payload":{"kind":"mini_lesson","locale":"en","locale_state":"reviewed","title":"Do I have to pay dues or a fee to keep my public-sector job?","body":"No, not as a condition of the job. In Janus v. AFSCME (2018), the U.S. Supreme Court held that taking agency fees from public employees who do not consent violates the First Amendment. No agency fee or other payment to a public-sector union may be taken from a nonmember's wages unless the employee affirmatively consents. Massachusetts law (c. 150E, s. 12) still contains older service-fee language, but the Massachusetts Department of Labor Relations (DLR) says agency shop clauses in contracts are invalid under Janus. If you choose to be a member, your union will usually require dues. Ask your steward about your own situation.","attribution":"","source":"Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 12, retrieved Oct 12, 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section12); Massachusetts Department of Labor Relations (mass.gov), DLR Q&A re: Janus v. AFSCME, retrieved Oct 12, 2026 (https://www.mass.gov/info-details/dlr-qa-re-janus-v-american-fed-of-state-cty-muni-employees); Legal Information Institute, Cornell Law School (law.cornell.edu), Janus v. AFSCME, Council 31, 585 U.S. 878 (2018), retrieved Oct 12, 2026 (https://www.law.cornell.edu/supremecourt/text/16-1466)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","dues"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-do-i-have-to-pay-dues-or-a-fee","locale":"en","record":{"provenance_id":"prov-69a4ca0c77caef59d33f28b6170ebcc42ba3ca59b28fb150101ce22f64cd1ab4","source":{"url":"https://app.example.invalid/#faq-do-i-have-to-pay-dues-or-a-fee","publisher":"Union Ground platform content (authored draft)","title":"Do I have to pay dues or a fee to keep my public-sector job?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"b4c09ffff9ec9c4fdc27074b28d0561c9a07422079d1bada03c18a27a1910d9b","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-7c255060c89c56d25d4d1d481d5c5da47f0d010a74612fcd44ee8468f1a7078b","prov-c903fcab77e757f1559444092413acbfe9fc207cd2e13125b166275e66d3debc","prov-ed6d292fdea50b229279fec66618e88ec6bbee0014c2efc1caeebc71cb92f8dc"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"ma-150e-s12","provenance":{"provenance_id":"prov-7c255060c89c56d25d4d1d481d5c5da47f0d010a74612fcd44ee8468f1a7078b","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section12","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 12","document_date":null},"retrieved_at":"2026-10-12T07:04:47Z","content_sha256":"3e54d40301750ff00b237f964de8e42cd6fc5ff9bf34ebd909d46da1941076a1","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"dlr-janus-qa","provenance":{"provenance_id":"prov-c903fcab77e757f1559444092413acbfe9fc207cd2e13125b166275e66d3debc","source":{"url":"https://www.mass.gov/info-details/dlr-qa-re-janus-v-american-fed-of-state-cty-muni-employees","publisher":"Massachusetts Department of Labor Relations (mass.gov)","title":"DLR Q&A re: Janus v. AFSCME","document_date":null},"retrieved_at":"2026-10-12T07:09:24Z","content_sha256":"be82dac0fc704fa097700b92f1fe4f77ac9a8dc2af1ef8470b0d8dc14376d3c8","capture":{"method":"firecrawl"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"lii-janus","provenance":{"provenance_id":"prov-ed6d292fdea50b229279fec66618e88ec6bbee0014c2efc1caeebc71cb92f8dc","source":{"url":"https://www.law.cornell.edu/supremecourt/text/16-1466","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"Janus v. AFSCME, Council 31, 585 U.S. 878 (2018)","document_date":"2018-06-27"},"retrieved_at":"2026-10-12T07:07:27Z","content_sha256":"272817eb5c402a1bb57a8e481f2f67cf36ea84d422ee3a731fa6589636632f77","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2018-06-27","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"b0882b38-ea4b-50db-a018-6186c137bbe7","payload":{"kind":"mini_lesson","locale":"es","locale_state":"reviewed","title":"¿Tengo que pagar cuotas sindicales o una cuota de agencia para conservar mi empleo público?","body":"No como condición del empleo. En el caso Janus v. AFSCME (2018), la Corte Suprema de EE. UU. decidió que cobrar cuotas de agencia (agency fees) a empleados públicos que no dan su consentimiento viola la Primera Enmienda. No se puede descontar del salario de una persona no afiliada ninguna cuota de agencia ni otro pago a un sindicato del sector público, salvo que esa persona dé su consentimiento expreso. La ley de Massachusetts (c. 150E, sección 12) todavía tiene un texto antiguo sobre la cuota de servicio (service fee), pero el Departamento de Relaciones Laborales de Massachusetts (DLR) dice que, según Janus, las cláusulas de agencia en los contratos no son válidas. Si usted decide afiliarse, su sindicato normalmente le pedirá cuotas sindicales (dues). Pregunte a su delegado o delegada sindical sobre su situación.","attribution":"","source":"Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 12, consultada el 12 oct 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section12); Massachusetts Department of Labor Relations (mass.gov), DLR Q&A re: Janus v. AFSCME, consultada el 12 oct 2026 (https://www.mass.gov/info-details/dlr-qa-re-janus-v-american-fed-of-state-cty-muni-employees); Legal Information Institute, Cornell Law School (law.cornell.edu), Janus v. AFSCME, Council 31, 585 U.S. 878 (2018), consultada el 12 oct 2026 (https://www.law.cornell.edu/supremecourt/text/16-1466)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","dues"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-do-i-have-to-pay-dues-or-a-fee","locale":"es","record":{"provenance_id":"prov-69a4ca0c77caef59d33f28b6170ebcc42ba3ca59b28fb150101ce22f64cd1ab4","source":{"url":"https://app.example.invalid/#faq-do-i-have-to-pay-dues-or-a-fee","publisher":"Union Ground platform content (authored draft)","title":"Do I have to pay dues or a fee to keep my public-sector job?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"b4c09ffff9ec9c4fdc27074b28d0561c9a07422079d1bada03c18a27a1910d9b","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-7c255060c89c56d25d4d1d481d5c5da47f0d010a74612fcd44ee8468f1a7078b","prov-c903fcab77e757f1559444092413acbfe9fc207cd2e13125b166275e66d3debc","prov-ed6d292fdea50b229279fec66618e88ec6bbee0014c2efc1caeebc71cb92f8dc"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"ma-150e-s12","provenance":{"provenance_id":"prov-7c255060c89c56d25d4d1d481d5c5da47f0d010a74612fcd44ee8468f1a7078b","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section12","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 12","document_date":null},"retrieved_at":"2026-10-12T07:04:47Z","content_sha256":"3e54d40301750ff00b237f964de8e42cd6fc5ff9bf34ebd909d46da1941076a1","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"dlr-janus-qa","provenance":{"provenance_id":"prov-c903fcab77e757f1559444092413acbfe9fc207cd2e13125b166275e66d3debc","source":{"url":"https://www.mass.gov/info-details/dlr-qa-re-janus-v-american-fed-of-state-cty-muni-employees","publisher":"Massachusetts Department of Labor Relations (mass.gov)","title":"DLR Q&A re: Janus v. AFSCME","document_date":null},"retrieved_at":"2026-10-12T07:09:24Z","content_sha256":"be82dac0fc704fa097700b92f1fe4f77ac9a8dc2af1ef8470b0d8dc14376d3c8","capture":{"method":"firecrawl"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"lii-janus","provenance":{"provenance_id":"prov-ed6d292fdea50b229279fec66618e88ec6bbee0014c2efc1caeebc71cb92f8dc","source":{"url":"https://www.law.cornell.edu/supremecourt/text/16-1466","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"Janus v. AFSCME, Council 31, 585 U.S. 878 (2018)","document_date":"2018-06-27"},"retrieved_at":"2026-10-12T07:07:27Z","content_sha256":"272817eb5c402a1bb57a8e481f2f67cf36ea84d422ee3a731fa6589636632f77","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2018-06-27","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"abbaae39-d792-5894-ac97-5fcb049fb2c5","payload":{"kind":"mini_lesson","locale":"en","locale_state":"reviewed","title":"How are union dues taken out of my paycheck?","body":"In Massachusetts public employment, dues can be paid by payroll deduction under M.G.L. c. 180, s. 17A. You sign a written authorization telling your employer the amount to deduct for union dues or fees. The state treasurer, or your employer's treasurer, deducts that amount and sends it to the union's treasurer. Once a union is certified or recognized for your unit, these deductions may go only to that union. For cities, towns and counties, the section applies where it has been accepted. Keep a copy of the authorization you signed, and ask your steward if a deduction on your pay stub looks wrong.","attribution":"","source":"Massachusetts General Court (malegislature.gov), M.G.L. c. 180, section 17A, retrieved Oct 12, 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXII/Chapter180/Section17A)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","dues"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-how-are-dues-taken-from-my-pay","locale":"en","record":{"provenance_id":"prov-99e80cd08509f71205f00949110d6af05580b492495cd54fc75755c29901dbd6","source":{"url":"https://app.example.invalid/#faq-how-are-dues-taken-from-my-pay","publisher":"Union Ground platform content (authored draft)","title":"How are union dues taken out of my paycheck?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"40d7c2db08bb708127d925f1f40564772102c9adcd53781451acc520391b77fe","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-17cff664dffa35b5bbfdd7c4785d7040c1bf841748fc5e57610a0871dd00ab21"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"ma-180-s17a","provenance":{"provenance_id":"prov-17cff664dffa35b5bbfdd7c4785d7040c1bf841748fc5e57610a0871dd00ab21","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXII/Chapter180/Section17A","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 180, section 17A","document_date":null},"retrieved_at":"2026-10-12T07:04:55Z","content_sha256":"3d2d86f69e7270b5f92cca2383b925d042c103d9f47d320e36834be0222753f5","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"e128dd77-3bd9-56f6-ab57-d5b5c0cfdaf0","payload":{"kind":"mini_lesson","locale":"es","locale_state":"reviewed","title":"¿Cómo se descuentan las cuotas sindicales de mi cheque de pago?","body":"En el empleo público de Massachusetts, las cuotas sindicales (dues) se pueden pagar por descuento de nómina según la ley M.G.L. c. 180, sección 17A. Usted firma una autorización por escrito que indica a su empleador la cantidad que debe descontar para cuotas sindicales. El tesorero del estado, o el tesorero de su empleador, descuenta esa cantidad y la envía al tesorero del sindicato. Cuando un sindicato está certificado o reconocido para su unidad, esos descuentos solo pueden ir a ese sindicato. En ciudades, pueblos y condados, la sección se aplica donde se ha aceptado. Guarde una copia de la autorización que firmó y pregunte a su delegado o delegada sindical si un descuento en su talón de pago parece incorrecto.","attribution":"","source":"Massachusetts General Court (malegislature.gov), M.G.L. c. 180, section 17A, consultada el 12 oct 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXII/Chapter180/Section17A)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","dues"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-how-are-dues-taken-from-my-pay","locale":"es","record":{"provenance_id":"prov-99e80cd08509f71205f00949110d6af05580b492495cd54fc75755c29901dbd6","source":{"url":"https://app.example.invalid/#faq-how-are-dues-taken-from-my-pay","publisher":"Union Ground platform content (authored draft)","title":"How are union dues taken out of my paycheck?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"40d7c2db08bb708127d925f1f40564772102c9adcd53781451acc520391b77fe","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-17cff664dffa35b5bbfdd7c4785d7040c1bf841748fc5e57610a0871dd00ab21"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"ma-180-s17a","provenance":{"provenance_id":"prov-17cff664dffa35b5bbfdd7c4785d7040c1bf841748fc5e57610a0871dd00ab21","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXII/Chapter180/Section17A","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 180, section 17A","document_date":null},"retrieved_at":"2026-10-12T07:04:55Z","content_sha256":"3d2d86f69e7270b5f92cca2383b925d042c103d9f47d320e36834be0222753f5","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"0ad82194-9d30-57fe-a796-af68ea4ed022","payload":{"kind":"mini_lesson","locale":"en","locale_state":"reviewed","title":"Can I stop paying dues, and how?","body":"Start with the payroll deduction authorization you signed. Under M.G.L. c. 180, s. 17A, an authorization may be irrevocable for up to 1 year, and it can be revoked only on the terms written in it. If it does not state revocation terms, you can withdraw it by giving your employer at least 60 calendar days' written notice and filing a copy with the union's treasurer. The union's treasurer must tell the payroll office about a revocation within 15 calendar days of receiving it. The DLR notes that members usually must pay dues to stay members, so ask your steward what stopping means for you.","attribution":"","source":"Massachusetts General Court (malegislature.gov), M.G.L. c. 180, section 17A, retrieved Oct 12, 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXII/Chapter180/Section17A); Massachusetts Department of Labor Relations (mass.gov), DLR Q&A re: Janus v. AFSCME, retrieved Oct 12, 2026 (https://www.mass.gov/info-details/dlr-qa-re-janus-v-american-fed-of-state-cty-muni-employees)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","dues"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-how-do-i-stop-paying-dues","locale":"en","record":{"provenance_id":"prov-e3ebae680b89e4a78e06c28b7b5465c4822dd17667f6842267b7665ced54836b","source":{"url":"https://app.example.invalid/#faq-how-do-i-stop-paying-dues","publisher":"Union Ground platform content (authored draft)","title":"Can I stop paying dues, and how?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"9f66788c85fa574326d6ff4277a8e13bf2cf621f0594d9a30f17c8079e566647","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-17cff664dffa35b5bbfdd7c4785d7040c1bf841748fc5e57610a0871dd00ab21","prov-c903fcab77e757f1559444092413acbfe9fc207cd2e13125b166275e66d3debc"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"ma-180-s17a","provenance":{"provenance_id":"prov-17cff664dffa35b5bbfdd7c4785d7040c1bf841748fc5e57610a0871dd00ab21","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXII/Chapter180/Section17A","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 180, section 17A","document_date":null},"retrieved_at":"2026-10-12T07:04:55Z","content_sha256":"3d2d86f69e7270b5f92cca2383b925d042c103d9f47d320e36834be0222753f5","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"dlr-janus-qa","provenance":{"provenance_id":"prov-c903fcab77e757f1559444092413acbfe9fc207cd2e13125b166275e66d3debc","source":{"url":"https://www.mass.gov/info-details/dlr-qa-re-janus-v-american-fed-of-state-cty-muni-employees","publisher":"Massachusetts Department of Labor Relations (mass.gov)","title":"DLR Q&A re: Janus v. AFSCME","document_date":null},"retrieved_at":"2026-10-12T07:09:24Z","content_sha256":"be82dac0fc704fa097700b92f1fe4f77ac9a8dc2af1ef8470b0d8dc14376d3c8","capture":{"method":"firecrawl"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"2d9a4aa1-6623-51ef-a0f5-9be4ffea738b","payload":{"kind":"mini_lesson","locale":"es","locale_state":"reviewed","title":"¿Puedo dejar de pagar cuotas sindicales? ¿Cómo?","body":"Empiece por la autorización de descuento de nómina que firmó. Según la ley M.G.L. c. 180, sección 17A, una autorización puede ser irrevocable por un máximo de 1 año, y solo se puede revocar según los términos escritos en ella. Si no indica términos para revocarla, usted puede retirarla dando a su empleador un aviso por escrito con al menos 60 días calendario de anticipación y entregando una copia al tesorero del sindicato. El tesorero del sindicato debe avisar a la oficina de nómina sobre la revocación dentro de los 15 días calendario después de recibirla. El DLR señala que los miembros normalmente deben pagar cuotas para seguir siendo miembros; pregunte a su delegado o delegada sindical qué significa dejar de pagar en su caso.","attribution":"","source":"Massachusetts General Court (malegislature.gov), M.G.L. c. 180, section 17A, consultada el 12 oct 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXII/Chapter180/Section17A); Massachusetts Department of Labor Relations (mass.gov), DLR Q&A re: Janus v. AFSCME, consultada el 12 oct 2026 (https://www.mass.gov/info-details/dlr-qa-re-janus-v-american-fed-of-state-cty-muni-employees)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","dues"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-how-do-i-stop-paying-dues","locale":"es","record":{"provenance_id":"prov-e3ebae680b89e4a78e06c28b7b5465c4822dd17667f6842267b7665ced54836b","source":{"url":"https://app.example.invalid/#faq-how-do-i-stop-paying-dues","publisher":"Union Ground platform content (authored draft)","title":"Can I stop paying dues, and how?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"9f66788c85fa574326d6ff4277a8e13bf2cf621f0594d9a30f17c8079e566647","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-17cff664dffa35b5bbfdd7c4785d7040c1bf841748fc5e57610a0871dd00ab21","prov-c903fcab77e757f1559444092413acbfe9fc207cd2e13125b166275e66d3debc"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"ma-180-s17a","provenance":{"provenance_id":"prov-17cff664dffa