ce capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"usc-29-431","provenance":{"provenance_id":"prov-c7bfdf0c8b0ca70089e10fd447440bd95248d9e18bebf53e00f3ef20d903f99f","source":{"url":"https://www.law.cornell.edu/uscode/text/29/431","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"29 U.S. Code 431 - Report of labor organizations","document_date":null},"retrieved_at":"2026-10-12T07:05:57Z","content_sha256":"fbbc5d6b424aac107445ef5fed5e792fd59f0e2b96b3b87f0063b696b1af5228","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"4fa910f9-d2bb-57df-a28a-8cf3c5ec55d5","payload":{"kind":"mini_lesson","locale":"en","locale_state":"reviewed","title":"Can I see my union's finances?","body":"Yes, in most cases. In Massachusetts public employment, c. 150E, s. 14 says a union must make its annual financial report available to members within 90 days after its fiscal year ends, and file a copy with the state. The Department of Labor Relations (DLR) accepts public records requests. Unions covered by the federal Labor-Management Reporting and Disclosure Act (LMRDA) file LM-2, LM-3 or LM-4 reports that anyone can search in the OLMS Online Public Disclosure Room. Federal law also lets a member of those unions sue, for just cause, to examine the books needed to verify a report. Start by asking your union office for the latest report.","attribution":"","source":"Massachusetts Depa