method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"olms-disclosure","provenance":{"provenance_id":"prov-e137149bcb356d90f11b97116b55a2665e46357345e9b01e3e737449045ca86d","source":{"url":"https://www.dol.gov/agencies/olms/public-disclosure-room","publisher":"U.S. Department of Labor, Office of Labor-Management Standards (dol.gov)","title":"OLMS Online Public Disclosure Room","document_date":null},"retrieved_at":"2026-10-12T07:06:30Z","content_sha256":"d18858e69a7643a3cb7f1e74af2bb27b56e07dc08f545ead3fe973b7314c1936","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"usc-29-431","provenance":{"provenance_id":"prov-c7bfdf0c8b0ca70089e10fd447440bd95248d9e18bebf53e00f3ef20d903f99f","source":{"url":"https://www.law.cornell.edu/uscode/text/29/431","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"29 U.S. Code 431 - Report of labor organizations","document_date":null},"retrieved_at":"2026-10-12T07:05:57Z","content_sha256":"fbbc5d6b424aac107445ef5fed5e792fd59f0e2b96b3b87f0063b696b1af5228","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"93f85008-4fae-57b8-ae40-39e3734d8a7d","payload":{"kind":"mini_lesson","locale":"en","locale_state":"reviewed","title":"What is an LM-2?","body":"Form LM-2 is the most detailed annual financial report a union files with the U.S. Department of Labor's Office of Labor-Management Standards (OLMS). The form depends on the union's total annual receipts: LM-2 for $250,000 or more, LM-3 for $10,000 or more but less than $250,000, and LM-4 for less than $10,000. These reports are filed electronically within 90 days after the end of the union's fiscal year. Federal law says the annual report covers assets and liabilities, payments to each officer and to employees paid more than $10,000, loans, and other disbursements. Only unions covered by federal reporting law file them.","attribution":"","source":"U.S. Department of Labor, Office of Labor-Management Standards (dol.gov), Forms LM-1, LM-2, LM-3, LM-4, retrieved Oct 12, 2026 (https://www.dol.gov/agencies/olms/reports/forms/lm-1-lm-2-lm-3-lm-4); Legal Information Institute, Cornell Law School (law.cornell.edu), 29 U.S. Code 431 - Report of labor organizations, retrieved Oct 12, 2026 (https://www.law.cornell.edu/uscode/text/29/431)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","dues"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-what-is-an-lm-2","locale":"en","record":{"provenance_id":"prov-4ffe3cba40c43c3905c1a6e9254e6aa6d73433a4656a05548cf2ffd2c2bfa58f","source":{"url":"https://app.example.invalid/#faq-what-is-an-lm-2","publisher":"Union Ground platform content (authored draft)","title":"What is an LM-2?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"e68e06d01686f365d69bd61ee8161c28ab07dfdaf9c3aabb8f699c15f3fde146","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-a0469dbe1f767cb7754c49bc242efdef2902110d1e517a653d70ce793a2370a3","prov-c7bfdf0c8b0ca70089e10fd447440bd95248d9e18bebf53e00f3ef20d903f99f"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"olms-forms","provenance":{"provenance_id":"prov-a0469dbe1f767cb7754c49bc242efdef2902110d1e517a653d70ce793a2370a3","source":{"url":"https://www.dol.gov/agencies/olms/reports/forms/lm-1-lm-2-lm-3-lm-4","publisher":"U.S. Department of Labor, Office of Labor-Management Standards (dol.gov)","title":"Forms LM-1, LM-2, LM-3, LM-4","document_date":null},"retrieved_at":"2026-10-12T07:07:11Z","content_sha256":"9fbb66e530ef8f7e211ad292571c59132afdf4605b43889afe7bd0df388ede35","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"usc-29-431","provenance":{"provenance_id":"prov-c7bfdf0c8b0ca70089e10fd447440bd95248d9e18bebf53e00f3ef20d903f99f","source":{"url":"https://www.law.cornell.edu/uscode/text/29/431","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"29 U.S. Code 431 - Report of labor organizations","document_date":null},"retrieved_at":"2026-10-12T07:05:57Z","content_sha256":"fbbc5d6b424aac107445ef5fed5e792fd59f0e2b96b3b87f0063b696b1af5228","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"a2f55ff3-f778-5e9c-a4e5-392b2b93df5b","payload":{"kind":"mini_lesson","locale":"es","locale_state":"reviewed","title":"¿Qué es un LM-2?","body":"El formulario LM-2 es el informe financiero anual más detallado que un sindicato presenta ante la Oficina de Normas Laborales-Gerenciales (Office of Labor-Management Standards, OLMS) del Departamento de Trabajo de EE. UU. El formulario depende de los ingresos anuales totales del sindicato: LM-2 para $250,000 o más, LM-3 para $10,000 o más pero menos de $250,000, y LM-4 para menos de $10,000. Estos informes se presentan por vía electrónica dentro de los 90 días después del cierre del año fiscal del sindicato. La ley federal dice que el informe anual incluye activos y pasivos, pagos a cada funcionario y a los empleados que recibieron más de $10,000, préstamos y otros gastos. Solo los sindicatos cubiertos por la ley federal de informes los presentan.","attribution":"","source":"U.S. Department of Labor, Office of Labor-Management Standards (dol.gov), Forms LM-1, LM-2, LM-3, LM-4, consultada el 12 oct 2026 (https://www.dol.gov/agencies/olms/reports/forms/lm-1-lm-2-lm-3-lm-4); Legal Information Institute, Cornell Law School (law.cornell.edu), 29 U.S. Code 431 - Report of labor organizations, consultada el 12 oct 2026 (https://www.law.cornell.edu/uscode/text/29/431)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","dues"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-what-is-an-lm-2","locale":"es","record":{"provenance_id":"prov-4ffe3cba40c43c3905c1a6e9254e6aa6d73433a4656a05548cf2ffd2c2bfa58f","source":{"url":"https://app.example.invalid/#faq-what-is-an-lm-2","publisher":"Union Ground platform content (authored draft)","title":"What is an LM-2?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"e68e06d01686f365d69bd61ee8161c28ab07dfdaf9c3aabb8f699c15f3fde146","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-a0469dbe1f767cb7754c49bc242efdef2902110d1e517a653d70ce793a2370a3","prov-c7bfdf0c8b0ca70089e10fd447440bd95248d9e18bebf53e00f3ef20d903f99f"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"olms-forms","provenance":{"provenance_id":"prov-a0469dbe1f767cb7754c49bc242efdef2902110d1e517a653d70ce793a2370a3","source":{"url":"https://www.dol.gov/agencies/olms/reports/forms/lm-1-lm-2-lm-3-lm-4","publisher":"U.S. Department of Labor, Office of Labor-Management Standards (dol.gov)","title":"Forms LM-1, LM-2, LM-3, LM-4","document_date":null},"retrieved_at":"2026-10-12T07:07:11Z","content_sha256":"9fbb66e530ef8f7e211ad292571c59132afdf4605b43889afe7bd0df388ede35","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"usc-29-431","provenance":{"provenance_id":"prov-c7bfdf0c8b0ca70089e10fd447440bd95248d9e18bebf53e00f3ef20d903f99f","source":{"url":"https://www.law.cornell.edu/uscode/text/29/431","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"29 U.S. Code 431 - Report of labor organizations","document_date":null},"retrieved_at":"2026-10-12T07:05:57Z","content_sha256":"fbbc5d6b424aac107445ef5fed5e792fd59f0e2b96b3b87f0063b696b1af5228","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"3404b594-67a7-54a8-a0b6-6e6f62f0602c","payload":{"kind":"mini_lesson","locale":"en","locale_state":"reviewed","title":"Why can't I find an LM-2 for my public-sector union?","body":"OLMS reports are filed by labor organizations subject to the Labor-Management Reporting and Disclosure Act (LMRDA), and by unions under certain federal-employee laws. The LMRDA defines a labor organization by its dealings with \"employers\", and its definition of employer does not include the United States or any State or political subdivision. So a union made up only of state or local government employees may not be covered and may not file LM reports. That does not mean its finances are secret. In Massachusetts, c. 150E, s. 14 requires public-sector unions to give members an annual financial report and file a copy with the state.","attribution":"","source":"Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 14, retrieved Oct 12, 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section14); Legal Information Institute, Cornell Law School (law.cornell.edu), 29 U.S. Code 402 - Definitions (LMRDA), retrieved Oct 12, 2026 (https://www.law.cornell.edu/uscode/text/29/402); U.S. Department of Labor, Office of Labor-Management Standards (dol.gov), Forms LM-1, LM-2, LM-3, LM-4, retrieved Oct 12, 2026 (https://www.dol.gov/agencies/olms/reports/forms/lm-1-lm-2-lm-3-lm-4)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","dues"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-why-no-lm-report-for-my-union","locale":"en","record":{"provenance_id":"prov-35ca9235154889f8a09a2fa10509ca582eaa4396c776847b1056381e02856cd9","source":{"url":"https://app.example.invalid/#faq-why-no-lm-report-for-my-union","publisher":"Union Ground platform content (authored draft)","title":"Why can't I find an LM-2 for my public-sector union?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"c501b165db6a57e1e5c1aa6ff233462943aa3cbc367cec7a3d49b8de65ab09ca","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-1d3766372af5cf75318263f88ea09d0b0dcbac631a88e99684c6bd934bfcd0f6","prov-30e45a7bc7e1b4b3b3cba47cc0bcd2be7f99e80d204c2ea66b47b674a1a1af5e","prov-a0469dbe1f767cb7754c49bc242efdef2902110d1e517a653d70ce793a2370a3"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"ma-150e-s14","provenance":{"provenance_id":"prov-1d3766372af5cf75318263f88ea09d0b0dcbac631a88e99684c6bd934bfcd0f6","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section14","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 14","document_date":null},"retrieved_at":"2026-10-12T07:04:50Z","content_sha256":"31a58ca26d659f4afa3dfd930b83013fd481a6f996248495893d48e2a1eb644c","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"usc-29-402","provenance":{"provenance_id":"prov-30e45a7bc7e1b4b3b3cba47cc0bcd2be7f99e80d204c2ea66b47b674a1a1af5e","source":{"url":"https://www.law.cornell.edu/uscode/text/29/402","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"29 U.S. Code 402 - Definitions (LMRDA)","document_date":null},"retrieved_at":"2026-10-12T07:05:56Z","content_sha256":"5cbebb792d0505fb1a72f89392db71d1584fd829b93af2e2905a03f0eb5c1b47","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"olms-forms","provenance":{"provenance_id":"prov-a0469dbe1f767cb7754c49bc242efdef2902110d1e517a653d70ce793a2370a3","source":{"url":"https://www.dol.gov/agencies/olms/reports/forms/lm-1-lm-2-lm-3-lm-4","publisher":"U.S. Department of Labor, Office of Labor-Management Standards (dol.gov)","title":"Forms LM-1, LM-2, LM-3, LM-4","document_date":null},"retrieved_at":"2026-10-12T07:07:11Z","content_sha256":"9fbb66e530ef8f7e211ad292571c59132afdf4605b43889afe7bd0df388ede35","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"59759676-d51c-5385-aff8-cca6f2fc2bb4","payload":{"kind":"mini_lesson","locale":"es","locale_state":"reviewed","title":"¿Por qué no encuentro un LM-2 de mi sindicato del sector público?","body":"Los informes de la OLMS los presentan las organizaciones laborales sujetas a la ley Labor-Management Reporting and Disclosure Act (LMRDA), y los sindicatos regidos por ciertas leyes de empleados federales. La LMRDA define una organización laboral por su relación con \"empleadores\", y su definición de empleador no incluye a Estados Unidos ni a ningún estado o subdivisión política. Por eso, un sindicato formado solo por empleados del gobierno estatal o local puede no estar cubierto y no presentar informes LM. Eso no significa que sus finanzas sean secretas. En Massachusetts, la ley c. 150E, sección 14, exige que los sindicatos del sector público entreguen a sus miembros un informe financiero anual y presenten una copia ante el estado.","attribution":"","source":"Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 14, consultada el 12 oct 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section14); Legal Information Institute, Cornell Law School (law.cornell.edu), 29 U.S. Code 402 - Definitions (LMRDA), consultada el 12 oct 2026 (https://www.law.cornell.edu/uscode/text/29/402); U.S. Department of Labor, Office of Labor-Manage