n14); Legal Information Institute, Cornell Law School (law.cornell.edu), 29 U.S. Code 411 - Bill of rights; constitution and bylaws of labor organizations, retrieved Oct 12, 2026 (https://www.law.cornell.edu/uscode/text/29/411)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","dues"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-can-my-union-raise-dues-without-a-vote","locale":"en","record":{"provenance_id":"prov-d11fb24d9ddd1df523a97045852d61bdec47a2264bce590ad9ce932755ebc605","source":{"url":"https://app.example.invalid/#faq-can-my-union-raise-dues-without-a-vote","publisher":"Union Ground platform content (authored draft)","title":"Can my union raise dues without a vote?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"bed26c371bbdc6e347cb8d912138c5aeaef5231d7e4a9a44b91365a164c1837c","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-1d3766372af5cf75318263f88ea09d0b0dcbac631a88e99684c6bd934bfcd0f6","prov-1b9c459692a115193a6b908ee3697b0688a17441c3091f34b1518e4be7ea1d9b"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"ma-150e-s14","provenance":{"provenance_id":"prov-1d3766372af5cf75318263f88ea09d0b0dcbac631a88e99684c6bd934bfcd0f6","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section14","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 14","document_date":null},"retrieved_at":"2026-10-12T07:04:50Z","content_sha256":"31a58ca26d659f4afa3dfd930b83013fd481a6f996248495893d48e2a1eb644c","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"usc-29-411","provenance":{"provenance_id":"prov-1b9c459692a115193a6b908ee3697b0688a17441c3091f34b1518e4be7ea1d9b","source":{"url":"https://www.law.cornell.edu/uscode/text/29/411","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"29 U.S. Code 411 - Bill of rights; constitution and bylaws of labor organizations","document_date":null},"retrieved_at":"2026-10-12T07:05:58Z","content_sha256":"a4bad78c1e6e0fac5ed46e8a7e927e4aa0244bea5d6bf9029fe03fe66a21cd42","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"4cde2698-1c3b-5649-a138-0ab0d6706f4c","payload":{"kind":"mini_lesson","locale":"es","locale_state":"reviewed","title":"¿Puede mi sindicato subir las cuotas sin una votación?","body":"En un sindicato local cubierto por la ley federal Labor-Management Reporting and Disclosure Act (LMRDA), un aumento de cuotas requiere el voto de la mayoría, en votación secreta, de los miembros en regla, ya sea en una reunión de miembros con aviso razonable o en un referéndum de los miembros. Los sindicatos nacionales tienen otras opciones, como una votación en convención. En un sindicato que la LMRDA tal vez no cubra, como uno formado solo por empleados del gobierno estatal o local, revise su constitución y sus estatutos para conocer las reglas. En Massachusetts, un sindicato del sector público debe presentar ante el estado una declaración con su escala de cuotas, cuotas de iniciación, multas y contribuciones especiales.","attribution":"","source":"Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 14, consultada el 12 oct 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section14); Legal Information Institute, Cornell Law School (law.cornell.edu), 29 U.S. Code 411 - Bill of rights; constitution and bylaws of labor organizations, consultada el 12 oct 2026 (https://www.law.cornell.edu/uscode/text/29/411)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","dues"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-can-my-union-raise-dues-without-a-vote","locale":"es","record":{"provenance_id":"prov-d11fb24d9ddd1df523a97045852d61bdec47a2264bce590ad9ce932755ebc605","source":{"url":"https://app.example.invalid/#faq-can-my-union-raise-dues-without-a-vote","publisher":"Union Ground platform content (authored draft)","title":"Can my union raise dues without a vote?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"bed26c371bbdc6e347cb8d912138c5aeaef5231d7e4a9a44b91365a164c1837c","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-1d3766372af5cf75318263f88ea09d0b0dcbac631a88e99684c6bd934bfcd0f6","prov-1b9c459692a115193a6b908ee3697b0688a17441c3091f34b1518e4be7ea1d9b"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"ma-150e-s14","provenance":{"provenance_id":"prov-1d3766372af5cf75318263f88ea09d0b0dcbac631a88e99684c6bd934bfcd0f6","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section14",