":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"nlrb-wages","provenance":{"provenance_id":"prov-b4f97dd512f7aa26017b563ab5584d53eb4fe725b5879fd48ab037e0eb68a5f6","source":{"url":"https://www.nlrb.gov/about-nlrb/rights-we-protect/your-rights/your-rights-to-discuss-wages","publisher":"National Labor Relations Board (nlrb.gov)","title":"Your Rights to Discuss Wages","document_date":null},"retrieved_at":"2026-10-12T07:07:06Z","content_sha256":"50efe865af8a64a1058b1175720ddfe3fd9bf684c0d17f16453ae75f1bd35fd0","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"ma-150e-s2","provenance":{"provenance_id":"prov-126932b67a9f47b18d5e6fbf72e8e8f9d02d5bd1e8c15f9323576ecb22e2fbce","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section2","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 2","document_date":null},"retrieved_at":"2026-10-12T07:04:32Z","content_sha256":"0ebbd12fb8b21954f920a48d5eb9c06c655996c8305010873f260f821aac1207","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"50b57842-1c06-5d03-a0a9-d6574c37e509","payload":{"kind":"mini_lesson","locale":"es","locale_state":"reviewed","title":"¿Puedo hablar de mi salario con mis compañeros de trabajo?","body":"Para la mayoría de los trabajadores del sector privado, sí. La Junta Nacional de Relaciones Laborales (NLRB) dice que los empleados cubiertos por la National Labor Relations Act (NLRA) tienen derecho a hablar con sus compañeros sobre salarios, y que las reglas que lo prohíben son ilegales. La NLRA no cubre a los empleadores del gobierno estatal o local. En el empleo público de Massachusetts, la ley c. 150E protege las actividades concertadas legales de ayuda o protección mutua, y el Departamento de Relaciones Laborales (DLR) incluye unirse para investigar salarios como actividad protegida. La NLRB también señala que las reglas sobre el uso del equipo del empleador pueden seguir aplicando. Si le dicen que no hable de su salario, anote lo que le dijeron y hable con su delegado o delegada sindical.","attribution":"","source":"Massachusetts Department of Labor Relations (mass.gov), C. Employee Rights to Organize and Bargain Collectively, consultada el 12 oct 2026 (https://www.mass.gov/info-details/c-employee-rights-to-organize-and-bargain-collectively); Legal Information Institute, Cornell Law School (law.cornell.edu), 29 U.S. Code 152 - Definitions (NLRA), consultada el 12 oct 2026 (https://www.law.cornell.edu/uscode/text/29/152); National Labor Relations Board (nlrb.gov), Your Rights to Discuss Wages, consultada el 12 oct 2026 (https://www.nlrb.gov/about-nlrb/rights-we-protect/your-rights/your-rights-to-discuss-wages); Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 2, consultada el 12 oct 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section2)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","rights-at-work"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-can-i-talk-about-my-pay","locale":"es","record":{"provenance_id":"prov-2a9ce7c0d147ff15284e345fbc361d9d360363570105b01b5d2ea9673dc92f26","source":{"url":"https://app.example.invalid/#faq-can-i-talk-about-my-pay","publisher":"Union Ground platform content (authored draft)","title":"Can I talk about my pay with my coworkers?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"5955d55be1acedeb0ce2281e9cb18bdc85795241a910ccab1bd115acaa6c57ca","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-6473f4f511b5363ca750d7ad44e1eb333241e658a9f60467349afd54d6e12501","prov-12171ec99baffa229634d78d17382025affed91de92a3f43a6893ea0faa9e051","prov-b4f97dd512f7aa26017b563ab5584d53eb4fe725b5879fd48ab037e0eb68a5f6","prov-126932b67a9f47b18d5e6fbf72e8e8f9d02d5bd1e8c15f9323576ecb22e2fbce"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.