iew","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"usc-29-158","provenance":{"provenance_id":"prov-15953b3894cd7ef79265a20366d68fbf4aadd7b1b109f7cefa4ccd5f45fc0a9f","source":{"url":"https://www.law.cornell.edu/uscode/text/29/158","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"29 U.S. Code 158 - Unfair labor practices","document_date":null},"retrieved_at":"2026-10-12T07:05:55Z","content_sha256":"014b25090e1b89bae25621eefa89fcd0a9e233d8a1233d5d7dbf6a689a9bb970","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"ma-150e-s10","provenance":{"provenance_id":"prov-2c059c955d72c4c595e3f43bc0687c642ae14534a28bd6775c9da73615b1639b","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section10","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 10","document_date":null},"retrieved_at":"2026-10-12T07:04:45Z","content_sha256":"666745eb1ada7ab2249397939fb9f0de5e86cf19bc5d3612ae8072618feec42d","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"ma-150e-s11","provenance":{"provenance_id":"prov-d4990f7ba5c14c5bdad936818f6f8ca9730e5ee9d6e76caaf67c03a039b2ae7f","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section11","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 11","document_date":null},"retrieved_at":"2026-10-12T07:04:46Z","content_sha256":"6ea055696317c50f44dc97d7259cefd302236184f44d5ac9d53fbdc50ac7436b","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"d434744f-0e65-5d4c-aba0-84ac9abdf3ab","payload":{"kind":"mini_lesson","locale":"en","locale_state":"reviewed","title":"What counts as protected concerted activity?","body":"Concerted activity is when two or more employees act together for their mutual aid or protection about their working conditions. Under the NLRA, the National Labor Relations Board (NLRB) says one employee can also be engaged in it when acting for coworkers or bringing group complaints to the employer. For Massachusetts public employees, the Department of Labor Relations (DLR) has found protected activity in examples such as writing to supervisors to complain about working conditions, publicly protesting working conditions, wearing union insignia at work, and starting a grievance. Section 2 of c. 150E protects this activity in Massachusetts public employment; Section 7 of the NLRA protects it for most private-sector workers.","attribution":"","source":"Massachusetts Department of Labor Relations (mass.gov), C. Employee Rights to Organize and Bargain Collectively, retrieved Oct 12, 2026 (https://www.mass.gov/info-details/c-employee-rights-to-organize-and-bargain-collectively); National Labor Relations Board (nlrb.gov), Employee Rights, retrieved Oct 12, 2026 (https://www.nlrb.gov/about-nlrb/rights-we-protect/your-rights/employee-rights); Legal Information Institute, Cornell Law School (law.cornell.edu), 29 U.S. Code 157 - Right of employees as to organization, collective bargaining, etc., retrieved Oct 12, 2026 (https://www.law.cornell.edu/uscode/text/29/157)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","rights-at-work"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-what-is-protected-concerted-activity","locale":"en","record":{"provenance_id":"prov-3ab5c9ff43a7c368dfc516fa3a1ae06423d781205b39bc7b31187435e84aebdc","source":{"url":"https://app.example.invalid/#faq-what-is-protected-concerted-activity","publisher":"Union Ground platform content (authored draft)","title":"What counts as protected concerted activity?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"d78114f34984d942b3d0f865fb0270bdc4c7b5494284b7b443cc65348386f626","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-6473f4f511b5363ca750d7ad44e1eb333241e658a9f60467349afd54d6e12501","prov-31c5feb31634e523cfc4869623a38392dd0108b7938673b4a91ddce23964c9