890c5f9066d3b93b408a311d10a6f66889a30b0f","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"usc-29-157","provenance":{"provenance_id":"prov-ee0a7a5424b5b54a82eb5771b972cd35a39c6891abe1eda788779ef88ab7441f","source":{"url":"https://www.law.cornell.edu/uscode/text/29/157","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"29 U.S. Code 157 - Right of employees as to organization, collective bargaining, etc.","document_date":null},"retrieved_at":"2026-10-12T07:05:54Z","content_sha256":"716bc440823e72f826ece9e4cb00a54fba287f977f7dd5908bee58bfa92aeb94","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"fff3e71c-8edf-58f8-a2d2-38208705fa9a","payload":{"kind":"mini_lesson","locale":"es","locale_state":"reviewed","title":"¿Qué se considera actividad concertada protegida?","body":"La actividad concertada ocurre cuando dos o más empleados actúan juntos para su ayuda o protección mutua sobre sus condiciones de trabajo. Según la NLRA, la Junta Nacional de Relaciones Laborales (NLRB) dice que un solo empleado también puede realizarla cuando actúa en nombre de sus compañeros o presenta quejas del grupo al empleador. Para los empleados públicos de Massachusetts, el Departamento de Relaciones Laborales (DLR) ha considerado protegidos ejemplos como escribir a los supervisores para quejarse de las condiciones de trabajo, protestar públicamente por esas condiciones, usar insignias sindicales en el trabajo e iniciar una queja formal (grievance). La sección 2 de la ley c. 150E protege esta actividad en el empleo público de Massachusetts; la sección 7 de la NLRA la protege para la mayoría de los trabajadores del sector privado.","attribution":"","source":"Massachusetts Department of Labor Relations (mass.gov), C. Employee Rights to Organize and Bargain Collectively, consultada el 12 oct 2026 (https://www.mass.gov/info-details/c-employee-rights-to-organize-and-bargain-collectively); National Labor Relations Board (nlrb.gov), Employee Rights, consultada el 12 oct 2026 (https://www.nlrb.gov/about-nlrb/rights-we-protect/your-rights/employee-rights); Legal Information Institute, Cornell Law School (law.cornell.edu), 29 U.S. Code 157 - Right of employees as to organization, collective bargaining, etc., consultada el 12 oct 2026 (https://www.law.cornell.edu/uscode/text/29/157)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","rights-at-work"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-what-is-protected-concerted-activity","locale":"es","record":{"provenance_id":"prov-3ab5c9ff43a7c368dfc516fa3a1ae06423d781205b39bc7b31187435e84aebdc","source":{"url":"https://app.example.invalid/#faq-what-is-protected-concerted-activity","