ttp-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"wex-just-cause","provenance":{"provenance_id":"prov-a252a54114c22a6d252ab3ac7d7727e75fae4132c5ec649fa68a5f2eaf0dc244","source":{"url":"https://www.law.cornell.edu/wex/just_cause","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"Wex: just cause","document_date":null},"retrieved_at":"2026-10-12T07:06:04Z","content_sha256":"6d17b9773f66920da0255b8f91300127cb21cd817f90bdcaed563d1a3a6109eb","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"wex-at-will","provenance":{"provenance_id":"prov-d05e125a2be43db18a146ae23a6efe54782449811eae5a351641aab26cfa55c5","source":{"url":"https://www.law.cornell.edu/wex/employment-at-will_doctrine","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"Wex: employment-at-will doctrine","document_date":null},"retrieved_at":"2026-10-12T07:06:07Z","content_sha256":"67b4646d4b108821fb9987fcbaa6a38a592599aa55d79655d59cc162722032a5","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"d27c0565-3565-528e-a7cd-0dc95ed9cfbe","payload":{"kind":"mini_lesson","locale":"es","locale_state":"reviewed","title":"¿Qué significa \"causa justa\" en la disciplina?","body":"La causa justa (just cause) pregunta si el empleador tenía una buena razón para despedir o disciplinar a un empleado. Se contrapone al empleo a voluntad (employment at will), la regla general en la que cualquiera de las partes puede terminar el empleo en cualquier momento y casi por cualquier razón. En Massachusetts, la ley de servicio civil dice que un empleado de servicio civil con permanencia no puede ser despedido, destituido ni suspendido por más de cinco días salvo por causa justa y después de los pasos que exige la ley. Su convenio colectivo (contrato) también puede fijar sus propias reglas de disciplina, así que lea su contrato y pregunte a su delegado o delegada sindical cómo se aplica la causa justa en su trabajo.","attribution":"","source":"Massachusetts General Court (malegislature.gov), M.G.L. c. 31, section 41, consultada el 12 oct 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleIV/Chapter31/Section41); Legal Information Institute, Cornell Law School (law.cornell.edu), Wex: just cause, consultada el 12 oct 2026 (https://www.law.cornell.edu/wex/just_cause); Legal Information Institute, Cornell Law School (law.cornell.edu), Wex: employment-at-will doctrine, consultada el 12 oct 2026 (https://www.law.cornell.edu/wex/employment-at-will_doctrine)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","rights-at-work"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-what-is-just-cause","locale":"es","record":{"provenance_id":"prov-7e15736ea1eddb3dd89a66b9eb461b0396d6b0acdb8f6d75718ab3613049ce85","source":{"url":"https://app.example.invalid/#faq-what-is-just-cause","publisher":"Union Ground platform content (authored draft)","title":"What does \"just cause\" mean for discipline?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"acf565d5f6723f5d3bef4d2c8f905f0c9ee41eb0ff63a5ea244a12ac6f28c37d","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-657cb2ea203fd171135d0e7f70dc54422182ba530b342c1049526a27c8ffd0b2","prov-a252a54114c22a6d252ab3ac7d7727e75fae4132c5ec649fa68a5f2eaf0dc244","prov-d05e125a2be43db18a146ae23a6efe54782449811eae5a351641aab26cfa55c5"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"ma-31-s41","provenance":{"provenance_id":"prov-657cb2ea203fd171135d0e7f70dc54422182ba530b342c1049526a27c8ffd0b2","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleIV/Chapter31/Section41","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 31, section 41","document_date":null},"retrieved_at":"2026-10-12T07:04:58Z","content_sha256":"be7da4f1f7a2936b9af4c28f22b61c7bf89fe5f31669464952e2e127f103a3a3","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"wex-just-cause","provenance":{"provenance_id":"prov-a252a54114c22a6d252ab3ac7d7727e75fae4132c5ec649fa68a5f2eaf0dc244","source":{"url":"https://www.law.cornell.edu/wex/just_cause","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"Wex: just cause","document_date":null},"retrieved_at":"2026-10-12T07:06:04Z","content_sha256":"6d17b9773f66920da0255b8f91300127cb21cd817f90bdcaed563d1a3a6109eb","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"wex-at-will","provenance":{"provenance_id":"prov-d05e125a2be43db18a146ae23a6efe54782449811eae5a351641aab26cfa55c5","source":{"url":"https://www.law.cornell.edu/wex/employment-at-will_doctrine","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"Wex: employment-at-will doctrine","document_date":null},"retrieved_at":"2026-10-12T07:06:07Z","content_sha256":"67b4646d4b108821fb9987fcbaa6a38a592599aa55d79655d59cc162722032a5","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"95278363-7fdc-5ead-aa28-9c61433569ee","payload":{"kind":"mini_lesson","locale":"en","locale_state":"reviewed","title":"Can union representatives meet with me at work?","body":"In Massachusetts public employment, yes, within limits set by c. 150E, s. 5A. Your employer must give the union that represents your unit access to you. That includes meeting with individual employees at the workplace during the work day to investigate and discuss grievances and workplace issues, and holding worksite meetings during lunch and other breaks or before and after work. The union may also use government buildings for meetings with unit members, as long as this does not interfere with government operations. Your home address and personal phone and email are not public records under this section. Ask your steward about meeting times at your worksite.","attribution":"","source":"Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 5A, retrieved Oct 12, 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section5A)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","rights-at-work"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-can-the-union-meet-me-at-work","locale":"en","record":{"provenance_id":"prov-3d16a71496e22cde5ed7b0f97b3eed3e3a4d961cee3a0965afea92aa9c250bf9","source":{"url":"https://app.example.invalid/#faq-can-the-union-meet-me-at-work","publisher":"Union Ground platform content (authored draft)","title":"Can union representatives meet with me at work?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"ed625a772445331c134f280ba6b3ea6eaced66aa4da4433ff47a31b150952bee","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-26ecba5c6cbc9ab17124be4fa65f69f9729091fb7a55b2df07dddb222a07b830"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"ma-150e-s5a","provenance":{"provenance_id":"prov-26ecba5c6cbc9ab17124be4fa65f69f9729091fb7a55b2df07dddb222a07b830","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section5A","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 5A","document_date":null},"retrieved_at":"2026-10-12T07:04:37Z","content_sha256":"3c86eead1a3985b3a257bfbedc1f1ca991f61f5637dd5e6c137ddae0bef13c36","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"c686cd54-4360-5a27-ac0c-fdb487e5ee31","payload":{"kind":"mini_lesson","locale":"es","locale_state":"reviewed","title":"¿Pueden los representantes sindicales reunirse conmigo en el trabajo?","body":"En el empleo público de Massachusetts, sí, dentro de los límites de la ley c. 150E, sección 5A. Su empleador debe dar acceso a usted al sindicato que representa a su unidad. Eso incluye reunirse con cada empleado en el lugar de trabajo durante la jornada para investigar y hablar sobre quejas formales (grievances) y asuntos laborales, y hacer reuniones en el lugar de trabajo durante el almuerzo y otros descansos o antes y después de la jornada. El sindicato también puede usar edificios del gobierno para reunirse con la unidad, siempre que no interfiera con las operaciones del gobierno. Según esta sección, su dirección y su teléfono y correo personales no son registros públicos. Pregunte a su delegado o delegada sindical sobre los horarios de reunión en su lugar de trabajo.","attribution":"","source":"Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 5A, consultada el 12 oct 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section5A)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","rights-at-work"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-can-the-union-meet-me-at-work","locale":"es","record":{"provenance_id":"prov-3d16a71496e22cde5ed7b0f97b3eed3e3a4d961cee3a0965afea92aa9c250bf9","source":{"url":"https://app.example.invalid/#faq-can-the-union-meet-me-at-work","publisher":"Union Ground platform content (authored draft)","title":"Can union representatives meet with me at work?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"ed625a772445331c134f280ba6b3ea6eaced66aa4da4433ff47a31b150952bee","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-26ecba5c6cbc9ab17124be4fa65f69f9729091fb7a55b2df07dddb222a07b830"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"ma-150e-s5a","provenance":{"provenance_id":"prov-26ecba5c6cbc9ab17124be4fa65f69f9729091fb7a55b2df07dddb222a07b830","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section5A","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 5A","document_date":null},"retrieved_at":"2026-10-12T07:04:37Z","content_sha256":"3c86eead1a3985b3a257bfbedc1f1ca991f61f5637dd5e6c137ddae0bef13c36","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"7e1e36e6-4d3e-5b55-aae0-bf187b3989d1","payload":{"kind":"mini_lesson","locale":"en","locale_state":"reviewed","title":"What is a grievance?","body":"A grievance is a formal complaint that the employer has violated workplace contract terms or labor policy. It can be filed by one employee or a group, and it may be about working conditions, pay, benefits, or treatment by supervisors. A Massachusetts State Auditor's report on the Department of Labor Relations describes a grievance as a complaint to management about actions that may have violated an employee's rights under a collective agreement or a law. The grievance procedure, the rules for presenting and resolving these disputes, is usually defined in your contract. Your steward can help you decide whether a problem is a grievance.","attribution":"","source":"Legal Information Institute, Cornell Law School (law.cornell.edu), Wex: grievance, retrieved Oct 12, 2026 (https://www.law.cornell.edu/wex/grievance); Massachusetts Office of the State Auditor (mass.gov), Audit of the Department of Labor Relations: overview of the Department of Labor Relations, retrieved Oct 12, 2026 (https://www.mass.gov/info-details/overview-of-the-department-of-labor-relations)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","grievances"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-what-is-a-grievance","locale":"en","record":{"provenance_id":"prov-a5dee5fb2d9311488a2f6c83ec7d5a3018b8066a8f87444904cfc2a672bc931c","source":{"url":"https://app.example.invalid/#faq-what-is-a-grievance","publisher":"Union Ground platform content (authored draft)","title":"What is a grievance?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"5f7cacf870583b79ed3775adc850a874905d8cf570e41abef1af31c4f3f0ea00","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-d3c11cdcb2fc2db731e8c3016853b534db924b729e8168353c3053d274ab68cd","prov-fe5f61dd7efae0ca8e4dc592e00f979fd4a5dba14ea2a585ca58e53bfd36d7e6"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"wex-grievance","provenance":{"provenance_id":"prov-d3c11cdcb2fc2db731e8c3016853b534db924b729e8168353c3053d274ab68cd","source":{"url":"https://www.law.cornell.edu/wex/grievance","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"Wex: grievance","document_date":null},"retrieved_at":"2026-10-12T07:06:18Z","content_sha256":"e342533040d64c8cbd8026a93163823f0bb1b9335d213da763466e14a1386af7","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"dlr-overview","provenance":{"provenance_id":"prov-fe5f61dd7efae0ca8e4dc592e00f979fd4a5dba14ea2a585ca58e53bfd36d7e6","source":{"url":"https://www.mass.gov/info-details/overview-of-the-department-of-labor-relations","publisher":"Massachusetts Office of the State Auditor (mass.gov)","title":"Audit of the Department of Labor Relations: overview of the Department of Labor Relations","document_date":null},"retrieved_at":"2026-10-12T07:08:58Z","content_sha256":"e70c1467eda23a7d338698577fc3b5005d7b2ec4318c6b29ede254be9e6d1e8e","capture":{"method":"firecrawl"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"8f595956-7b85-5db3-adab-2e78abb95fd1","payload":{"kind":"mini_lesson","locale":"es","locale_state":"reviewed","title":"¿Qué es una queja formal (grievance)?","body":"Una queja formal (grievance) es un reclamo formal de que el empleador violó los términos del contrato de trabajo o una política laboral. La puede presentar un empleado o un grupo, y puede tratar sobre condiciones de trabajo, salario, beneficios o el trato de los supervisores. Un informe de la Auditoría del Estado de Massachusetts (State Auditor) sobre el Departamento de Relaciones Laborales describe la queja formal como un reclamo a la gerencia por acciones que pueden haber violado los derechos de un empleado según un convenio colectivo o una ley. El procedimiento de quejas, es decir, las reglas para presentar y resolver estas disputas, normalmente está definido en su convenio colectivo (contrato). Su delegado o delegada sindical puede ayudarle a decidir si un problema es una queja formal.","attribution":"","source":"Legal Information Institute, Cornell Law School (law.cornell.edu), Wex: grievance, consultada el 12 oct 2026 (https://www.law.cornell.edu/wex/grievance); Massachusetts Office of the State Auditor (mass.gov), Audit of the Department of Labor Relations: overview of the Department of Labor Relations, consultada el 12 oct 2026 (https://www.mass.gov/info-details/overview-of-the-department-of-labor-relations)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","grievances"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-what-is-a-grievance","locale":"es","record":{"provenance_id":"prov-a5dee5fb2d9311488a2f6c83ec7d5a3018b8066a8f87444904cfc2a672bc931c","source":{"url":"https://app.example.invalid/#faq-what-is-a-grievance","publisher":"Union Ground platform content (authored draft)","title":"What is a grievance?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"5f7cacf870583b79ed3775adc850a874905d8cf570e41abef1af31c4f3f0ea00","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-d3c11cdcb2fc2db731e8c3016853b534db924b729e8168353c3053d274ab68cd","prov-fe5f61dd7efae0ca8e4dc592e00f979fd4a5dba14ea2a585ca58e53bfd36d7e6"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"wex-grievance","provenance":{"provenance_id":"prov-d3c11cdcb2fc2db731e8c3016853b534db924b729e8168353c3053d274ab68cd","source":{"url":"https://www.law.cornell.edu/wex/grievance","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"Wex: grievance","document_date":null},"retrieved_at":"2026-10-12T07:06:18Z","content_sha256":"e342533040d64c8cbd8026a93163823f0bb1b9335d213da763466e14a1386af7","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"dlr-overview","provenance":{"provenance_id":"prov-fe5f61dd7efae0ca8e4dc592e00f979fd4a5dba14ea2a585ca58e53bfd36d7e6","source":{"url":"https://www.mass.gov/info-details/overview-of-the-department-of-labor-relations","publisher":"Massachusetts Office of the State Auditor (mass.gov)","title":"Audit of the Department of Labor Relations: overview of the Department of Labor Relations","document_date":null},"retrieved_at":"2026-10-12T07:08:58Z","content_sha256":"e70c1467eda23a7d338698577fc3b5005d7b2ec4318c6b29ede254be9e6d1e8e","capture":{"method":"firecrawl"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"08762773-c4f8-5e03-a406-8c00f69aed88","payload":{"kind":"mini_lesson","locale":"en","locale_state":"reviewed","title":"What is not a grievance?","body":"A grievance is aimed at management and is tied to rights in your contract, a covered policy, or a law. In Massachusetts public employment, c. 150E, s. 8 lets a contract send disputes about the interpretation or application of the written agreement to final and binding arbitration. A problem your contract does not address may not fit that procedure. Some problems go elsewhere: a complaint that your employer retaliated for union activity, or that your union failed to represent you properly, can be a prohibited practice charge at the Department of Labor Relations (DLR). Your steward can tell you which route fits your problem and your contract.","attribution":"","source":"Massachusetts Department of Labor Relations (mass.gov), F. Prohibited Practices, retrieved Oct 12, 2026 (https://www.mass.gov/info-details/f-prohibited-practic