150E, section 8","document_date":null},"retrieved_at":"2026-10-12T07:04:41Z","content_sha256":"d35cfe7426c0d1815be725457582e2337b3ebf9a24fb26b4f880b7cd19a659c7","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"dlr-c-arb-mediation","provenance":{"provenance_id":"prov-28a7806565901ce7eb42c9a4b7bf47afe709c5ef6ea4283c5345f08424626c8d","source":{"url":"https://www.mass.gov/info-details/c-arbitration-and-mediation-services","publisher":"Massachusetts Department of Labor Relations (mass.gov)","title":"C. Arbitration and Mediation Services","document_date":null},"retrieved_at":"2026-10-12T07:09:19Z","content_sha256":"88d732e76e15f49a67684e09163821c1874766ed51e770d043240988162e47ae","capture":{"method":"firecrawl"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"1caf2b11-9ddc-588d-a7e1-0150426750db","payload":{"kind":"mini_lesson","locale":"en","locale_state":"reviewed","title":"What is arbitration, and is the decision final?","body":"Arbitration is a way to settle a dispute out of court: a neutral arbitrator hears the case and decides it by issuing an award. At the Massachusetts Department of Labor Relations (DLR), a single arbitrator hears and decides the case, and the award usually comes some time after the written briefs are submitted. Under c. 150E, s. 8, a contract may include a grievance procedure ending in final and binding arbitration; if it does not, the DLR can order binding arbitration at either party's request. Awards are hard to overturn. Under c. 150C, s. 11, a court vacates an award only on narrow grounds, such as fraud, evident partiality, or an arbitrator exceeding their powers, and the application must be made within 30 days.","attribution":"","source":"Legal Information Institute, Cornell Law School (law.cornell.edu), Wex: arbitration, retrieved Oct 12, 2026 (https://www.law.cornell.edu/wex/arbitration); Massachusetts General Court (malegislature.gov), M.G.L. c. 150C, section 11, retrieved Oct 12, 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150C/Section11); Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 8, retrieved Oct 12, 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section8); Massachusetts Department of Labor Relations (mass.gov), C. Arbitration and Mediation Services, retrieved Oct 12, 2026 (https://www.mass.gov/info-details/c-arbitration-and-mediation-services)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","grievances"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-what-is-arbitration-and-is-it-final","locale":"en","record":{"provenance_id":"prov-1d1d90d991dbe3ce075c34bf0ec97c9fa9e3c74c4f93cf4774963fa02b2d462f","source":{"url":"https://app.example.invalid/#faq-what-is-arbitration-and-is-it-final","publisher":"Union Ground platform content (authored draft)","title":"What is arbitration, and is the decision final?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"6d7bdab6931927cba6f6fe75e76a9a730d47f71ca84e91217dad5b0ee62296f5","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-5b66285ef3c364e2c5c4e1d10c385a66596632d1a6bd3950cdb3d107edb0ffb7","prov-ea398bb6f9ca494fd150f439e2be82ae24e592bce393c38a741aba6a4b90e9e4","prov-c4e88d90080bdab73b27a7cd4ea0379017407d40a749d99a3c94847982ef3c48","prov-28a7806565901ce7eb42c9a4b7bf47afe709c5ef6ea4283c5345f08424626c8d"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"wex-arbitration","provenance":{"provenance_id":"prov-5b66285ef3c364e2c5c4e1d10c385a66596632d1a6bd3950cdb3d107edb0ffb7","source":{"url":"https://www.law.cornell.edu/wex/arbitration","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"Wex: arbitration","document_date":null},"retrieved_at":"2026-10-12T07:06:02Z","content_sha256":"a4f2bcc1f42f908946baad38b5991b4ff499f90c6bc19ef081e58b3888985def","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"ma-150c-s11","provenance":{"provenance_id":"prov-ea398bb6f9ca494fd150f439e2be82ae24e592bce393c38a741aba6a4b90e9e4","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150C/Section11","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150C, section 11","document_date":null},"retrieved_at":"2026-10-12T07:14:51Z","content_sha256":"f2b4a8dee1a894555088aa810c414fe43fff7f2c84a7369838d9eae1c29ac1e0","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"ma-150e-s8","provenance":{"provenance_id":"prov-c4e88d90080bdab73b27a7cd4ea0379017407d40a749d99a3c94847982ef3c48","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section8","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 8","document_date":null},"retrieved_at":"2026-10-12T07:04:41Z","content_sha256":"d35cfe7426c0d1815be725457582e2337b3ebf9a24fb26b4f880b7cd19a659c7","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"dlr-c-arb-mediation","provenance":{"provenance_id":"prov-28a7806565901ce7eb42c9a4b7bf47afe709c5ef6ea4283c5345f08424626c8d","source":{"url":"https://www.mass.gov/info-details/c-arbitration-and-mediation-services","publisher":"Massachusetts Department of Labor Relations (mass.gov)","title":"C. Arbitration and Mediation Services","document_date":null},"retrieved_at":"2026-10-12T07:09:19Z","content_sha256":"88d732e76e15f49a67684e09163821c1874766ed51e770d043240988162e47ae","capture":{"method":"firecrawl"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"e0cfeb63-20cd-5423-a711-19c40696cfb5","payload":{"kind":"mini_lesson","locale":"es","locale_state":"reviewed","title":"¿Qué es el arbitraje y la decisión es definitiva?","body":"El arbitraje (arbitration) es una forma de resolver una disputa fuera de los tribunales: un árbitro neutral escucha el caso y lo decide emitiendo un laudo (award). En el Departamento de Relaciones Laborales de Massachusetts (DLR), un solo árbitro escucha y decide el caso, y el laudo suele llegar un tiempo después de que se presentan los escritos. Según la ley c. 150E, sección 8, un contrato puede incluir un procedimiento de quejas que termine en arbitraje final y obligatorio; si no lo incluye, el DLR puede ordenar arbitraje obligatorio a pedido de cualquiera de las partes. Es difícil anular un laudo. Según la ley c. 150C, sección 11, un tribunal anula un laudo solo por motivos limitados, como fraude, parcialidad evidente o que el árbitro se excedió en sus poderes, y la solicitud debe hacerse dentro de 30 días.","attribution":"","source":"Legal Information Institute, Cornell Law School (law.cornell.edu), Wex: arbitration, consultada el 12 oct 2026 (https://www.law.cornell.edu/wex/arbitration); Massachusetts General Court (malegislature.gov), M.G.L. c. 150C, section 11, consultada el 12 oct 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150C/Section11); Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 8, consultada el 12 oct 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section8); Massachusetts Department of Labor Relations (mass.gov), C. Arbitration and Mediation Services, consultada el 12 oct 2026 (https://www.mass.gov/info-details/c-arbitration-and-mediation-services)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","grievances"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-what-is-arbitration-and-is-it-final","locale":"es","record":{"provenance_id":"prov-1d1d90d991dbe3ce075c34bf0ec97c9fa9e3c74c4f93cf4774963fa02b2d462f","source":{"url":"https://app.example.invalid/#faq-what-is-arbitration-and-is-it-final","publisher":"Union Ground platform content (authored draft)","title":"What is arbitration, and is the decision final?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"6d7bdab6931927cba6f6fe75e76a9a730d47f71ca84e91217dad5b0ee62296f5","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-