":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150C, section 11","document_date":null},"retrieved_at":"2026-10-12T07:14:51Z","content_sha256":"f2b4a8dee1a894555088aa810c414fe43fff7f2c84a7369838d9eae1c29ac1e0","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"ma-150e-s8","provenance":{"provenance_id":"prov-c4e88d90080bdab73b27a7cd4ea0379017407d40a749d99a3c94847982ef3c48","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section8","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 8","document_date":null},"retrieved_at":"2026-10-12T07:04:41Z","content_sha256":"d35cfe7426c0d1815be725457582e2337b3ebf9a24fb26b4f880b7cd19a659c7","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"dlr-c-arb-mediation","provenance":{"provenance_id":"prov-28a7806565901ce7eb42c9a4b7bf47afe709c5ef6ea4283c5345f08424626c8d","source":{"url":"https://www.mass.gov/info-details/c-arbitration-and-mediation-services","publisher":"Massachusetts Department of Labor Relations (mass.gov)","title":"C. Arbitration and Mediation Services","document_date":null},"retrieved_at":"2026-10-12T07:09:19Z","content_sha256":"88d732e76e15f49a67684e09163821c1874766ed51e770d043240988162e47ae","capture":{"method":"firecrawl"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"b3397553-fe8d-5353-a7bf-8c738b777d99","payload":{"kind":"mini_lesson","locale":"en","locale_state":"reviewed","title":"What if my union decides not to take my grievance to arbitration?","body":"In Vaca v. Sipes (1967), a private-sector case, the U.S. Supreme Court said an employee does not have an absolute right to have a grievance taken to arbitration, but a union may not arbitrarily ignore a meritorious grievance or handle it in a perfunctory way. In Massachusetts public employment, the Department of Labor Relations (DLR) says a union breaches its duty of fair representation if its actions are unlawfully motivated, arbitrary, perfunctory, or reflect inexcusable neglect. An honest mistake or simple negligence, alone, is not a breach. You can file a prohibited practice charge at the DLR within six months. First ask your steward or a union officer to explain the decision.","attribution":"","source":"Massachusetts Department of Labor Relations (mass.gov), Public sector unfair labor practice charge, retrieved Oct 12, 2026 (https://www.mass.gov/how-to/public-sector-unfair-labor-practice-charge); Massachusetts Department of Labor Relations (mass.gov), F. Prohibited Practices, retrieved Oct 12, 2026 (https://www.mass.gov/info-details/f-prohibited-practices); Legal Information Institute, Cornell Law School (law.cornell.edu), Vaca v. Sipes, 386 U.S. 171 (1967), retrieved Oct 12, 2026 (https://www.law.cornell.edu/supremecourt/text/386/171)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","grievances"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-union-wont-take-my-grievance-to-arbitration","locale":"en","record":{"provenance_id":"prov-5b2d02572d11b118758f1d422795feae2ed7417b0750b93f77c90549ecb3deb7","source":{"url":"https://app.example.invalid/#faq-union-wont-take-my-grievance-to-arbitration","publisher":"Union Ground platform content (authored draft)","title":"What if my union decides not to take my grievance to arbitration?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"0a5f102f321049d1c655376462501c10e33a2a378ba81b1c8840bbbca8a3f854","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-8d886c64c852c30ba3c7840a80cd711d7fc31ef373b36ab5b1511b79f411d254","prov-ecae6940b308e391c248946ec43aa6ac002944d053d015fb9b902296489b0551","prov-868f67459135ea084c824d90c025cab0fd25b5e7966b4ded0382d99040dd5749"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"dlr-ulp-charge","provenance":{"provenance_id":"prov-8d886c64c852c30ba3c7840a80cd711d7fc31ef373b36ab5b1511b79f411d254","source":{"url":"https://www.mass.gov/how-to/public-sector-unfair-labor-practice-charge","publisher":"Massachusetts Department of Labor Relations (mass.gov)","title":"Public sector unfair labor practice charge","document_date":null},"retrieved_at":"2026-10-12T07:09:15Z","content_sha256":"a151c58def500412b27bc8f74f24865e90c2867a99c78cc29813dbb459e4c65f","capture":{"method":"firecrawl"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"dlr-f-prohibited","provenance":{"provenance_id":"prov-ecae6940b308e391c248946ec43aa6ac002944d053d015fb9b902296489b0551","source":{"url":"https://www.mass.gov/info-details/f-prohibited-practices","publisher":"Massachusetts Department of Labor Relations (mass.gov)","title":"F. Prohibited Practices","document_date":null},"retrieved_at":"2026-10-12T07:09:28Z","content_sha256":"f224cd36a7aed5e7970224b979c7bce2283f952dc3d88f3906e6f8873c11dfd5","capture":{"method":"firecrawl"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"lii-vaca","provenance":{"provenance_id":"prov-868f67459135ea084c824d90c025cab0fd25b5e7966b4ded0382d99040dd5749","source":{"url":"https://www.law.cornell.edu/supremecourt/text/386/171","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"Vaca v. Sipes, 386 U.S. 171 (1967)","document_date":"1967-02-27"},"retrieved_at":"2026-10-12T07:07:18Z","content_sha256":"165ea2a82bab9fec8b04580355af7dd8096102fa8bcf2b90410a069924d80c13","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"1967-02-27","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"16ab99cb-2861-50d6-a821-95f20802c0df","payload":{"kind":"mini_lesson","locale":"es","locale_state":"reviewed","title":"¿Qué pasa si mi sindicato decide no llevar mi queja formal a arbitraje?","body":"En el caso Vaca v. Sipes (1967), del sector privado, la Corte Suprema de EE. UU. dijo que un empleado no tiene un derecho absoluto a que su queja formal llegue a arbitraje, pero que un sindicato no puede ignorar arbitrariamente una queja con fundamento ni tramitarla de forma superficial. En el empleo público de Massachusetts, el Departamento de Relaciones Laborales (DLR) dice que un sindicato incumple su deber de representación justa (duty of fair representation) si actúa por motivos ilegales, de forma arbitraria o superficial, o con negligencia inexcusable. Un error honesto o una simple negligencia, por sí solos, no son un incumplimiento. Usted puede presentar un cargo por práctica prohibida ante el DLR dentro de los seis meses. Primero pida a su delegado o delegada sindical o a un funcionario del sindicato que le explique la decisión.","attribution":"","source":"Massachusetts Department of Labor Relations (mass.gov), Public sector unfair labor practice charge, consultada el 12 oct 2026 (https://www.mass.gov/how-to/public-sector-unfair-labor-practice-charge); Massachusetts Department of Labor Relations (mass.gov), F. Prohibited Practices, consultada el 12 oct 2026 (https://www.mass.gov/info-details/f-prohibited-practices); Legal Information Institute, Cornell Law School (law.cornell.edu), Vaca v. Sipes, 386 U.S. 171 (1967), consultada el 12 oct 2026 (https://www.law.cornell.edu/supremecourt/text/386/171)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","grievances"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-union-wont-take-my-grievance-to-arbitration","locale":"es","record":{"provenance_id":"prov-5b2d02572d11b118758f1d422795feae2ed7417b0750b93f77c90549ecb3deb7","source":{"url":"https://app.example.invalid/#faq-union-wont-take-my-grievance-to-arbitration","publisher":"Union Ground platform content (authored draft)","title":"What if my union decides not to take my grievance to arbitration?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"0a5f102f321049d1c655376462501c10e33a2a378ba81b1c8840bbbca8a3f854","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-8d886c64c852c30ba3c7840a80cd711d7fc31ef373b36ab5b1511b79f411d254","prov-ecae6940b308e391c248946ec43aa6ac002944d053d015fb9b902296489b0551","prov-868f67459135ea084c824