l."}}},{"source_key":"ma-150e-s9a","provenance":{"provenance_id":"prov-4ee5d941eb6b2e1e728f9f0cbf205976cd524466aed27e4b1677c0d842883c3b","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section9A","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 9A","document_date":null},"retrieved_at":"2026-10-12T07:04:43Z","content_sha256":"b6aa766c7446c969d6b3a80f6e192ff0392e004e5f9c4e013a2d690839c98d84","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"ma-150e-s1","provenance":{"provenance_id":"prov-946c243f5c2e016d2c7cca739060f56da00c7fdffa96b123a14c06623d3d9461","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section1","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 1","document_date":null},"retrieved_at":"2026-10-12T07:04:30Z","content_sha256":"f627eeb678daa6ec888fde9e8a968fbbbe17103a17d0ebfed7741f3453a9247c","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"nlrb-strike","provenance":{"provenance_id":"prov-6477d08d028441033a2ce28c282ad85b8a4210ac35c6d22840eeee4ed630988b","source":{"url":"https://www.nlrb.gov/about-nlrb/rights-we-protect/your-rights/nlra-and-the-right-to-strike","publisher":"National Labor Relations Board (nlrb.gov)","title":"The NLRA and the Right to Strike","document_date":null},"retrieved_at":"2026-10-12T07:07:03Z","content_sha256":"5dadbcee2a2e87dc4e3de59819cb3fbfea537acc8c9b3031c4abfdf16a52e8ae","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"1687b5fc-db56-51e6-a552-c9c24db3101a","payload":{"kind":"mini_lesson","locale":"es","locale_state":"reviewed","title":"¿Pueden hacer huelga los empleados públicos en Massachusetts?","body":"No. Según la ley c. 150E, sección 9A, ningún empleado público ni organización de empleados puede hacer huelga (strike), ni provocar, alentar o aprobar una huelga, paro, trabajo lento o retención de servicios. Si ocurre o está por ocurrir una huelga, el empleador pide al estado que investigue, y la aplicación de la ley puede llegar al tribunal superior. Según la sección 15, a los empleados no se les paga por los días de huelga y pueden enfrentar disciplina y despido. La definición de huelga de la ley sigue protegiendo su derecho a expresar una queja u opinión sobre las condiciones de trabajo. Los trabajadores del sector privado tienen derecho a la huelga según la NLRA, con muchos límites. Pregunte a su delegado o delegada sindical antes de unirse a cualquier acción laboral.","attribution":"","source":"Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 15, consultada el 12 oct 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section15); Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 9A, consultada el 12 oct 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section9A); Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 1, consultada el 12 oct 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section1); National Labor Relations Board (nlrb.gov), The NLRA and the Right to Strike, consultada el 12 oct 2026 (https://www.nlrb.gov/about-nlrb/rights-we-protect/your-rights/nlra-and-the-right-to-strike)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","bargaining"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-can-public-employees-strike-in-massachusetts","locale":"es","record":{"provenance_id":"prov-61489d5488b41c6f6f22d62c936264fe77edb58bc4a98127a80ce2d51cfdbfc9","source":{"url":"https://app.example.invalid/#faq-can-public-employees-strike-in-massachusetts","publisher":"Union Ground platform content (authored draft)","title":"Can public employees in Massachusetts strike?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"5d39e5bc4a58749d944882922370974a8e558648b4e1c704115a671978b261fc","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-78ae711e650c1f21b7e9abcd7774abce9ab70dd4490077e4a4b6a44fad7e3ba8","prov-4ee5d941eb6b2e1e728f9f0cbf205976cd524466aed27e4b1677c0d842883c3b","prov-946c243f5c2e016d2c7cca739060f