r","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"68add632-dfbe-5d55-a1af-d9bd1c35d6b1","payload":{"kind":"mini_lesson","locale":"en","locale_state":"reviewed","title":"Who approves the money for a public-sector contract?","body":"In Massachusetts, a contract's cost items need an appropriation from a legislative body. Under c. 150E, s. 7, most public employers must ask the appropriate legislative body for the money within 30 days after the contract is signed; if that body rejects the request, the cost items go back to the parties for more bargaining. For some employers, including the University of Massachusetts trustees, the courts' chief justice for administration and management, and county sheriffs, the request goes to the governor. If the governor does not recommend funding within 45 days, the request goes back to the parties. Legislative body includes the General Court, a city council, or town meeting.","attribution":"","source":"Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 1, retrieved Oct 12, 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section1); Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 7, retrieved Oct 12, 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section7)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","bargaining"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-who-approves-the-money-for-a-contract","locale":"en","record":{"provenance_id":"prov-c74608594605584f73c8adf8ceba590ec6e3fb64d600ae601514f9a59288b933","source":{"url":"https://app.example.invalid/#faq-who-approves-the-money-for-a-contract","publisher":"Union Ground platform content (authored draft)","title":"Who approves the money for a public-sector contract?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"bd2b4c497560c1d8d85535ef63c5aa61aef98918621aa3e11b0e8fb4bc0f5010","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-946c243f5c2e016d2c7cca739060f56da00c7fdffa96b123a14c06623d3d9461","prov-9ff70d90b04e4d4b84d074f2379281256c7d263dd1786e950bee8180dc12ab6c"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"ma-150e-s1","provenance":{"provenance_id":"prov-946c243f5c2e016d2c7cca739060f56da00c7fdffa96b123a14c06623d3d9461","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section1","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 1","document_date":null},"retrieved_at":"2026-10-12T07:04:30Z",