s","document_date":null},"retrieved_at":"2026-10-12T07:05:57Z","content_sha256":"fbbc5d6b424aac107445ef5fed5e792fd59f0e2b96b3b87f0063b696b1af5228","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"ma-150e-s7","provenance":{"provenance_id":"prov-9ff70d90b04e4d4b84d074f2379281256c7d263dd1786e950bee8180dc12ab6c","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section7","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 7","document_date":null},"retrieved_at":"2026-10-12T07:04:39Z","content_sha256":"79bd21e29442b6264292d5e9ab5b8c01075862c03bd3ac24ad0daa34520f21d7","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"c2b9ff61-0639-567c-ad6c-f7b9f4d297f4","payload":{"kind":"mini_lesson","locale":"en","locale_state":"reviewed","title":"How long can a contract last?","body":"In Massachusetts public employment, c. 150E, s. 7 says a collective bargaining agreement may not exceed a term of three years. The parties may, however, agree to a clause saying the contract's terms stay in full force beyond the three years until a successor agreement is voluntarily negotiated. Contracts also set out how they interact with certain laws: if a contract conflicts with statutes listed in s. 7(d), the contract generally prevails; for other statutes, the statute prevails. To find your contract's start and end dates, read your contract or ask your steward.","attribution":"","source":"Massachusetts Department of Labor Relations (mass.gov), FAQ - The Collective Bargaining Process, retrieved Oct 12, 2026 (https://www.mass.gov/info-details/faq-the-collective-bargaining-process); Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 7, retrieved Oct 12, 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section7)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","bargaining"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-how-long-can-a-contract-last","locale":"en","record":{"provenance_id":"prov-4bd675f6fb98154b5dc98f4ce8acc208d0eaf09c054f2318e3c12d63805d78b3","source":{"url":"https://app.example.invalid/#faq-how-long-can-a-contract-last","publisher":"Union Ground platform content (authored draft)","title":"How long can a contract last?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"ea8e44e1abf4fd3a589c29b93598eae180903c5adf4454746d98f104a5e3fb9d","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-8f25653210c21b4f2f69e663cae599