4Z","content_sha256":"29cb41bf93f0dc9cbeac6c370763eb7ef4a891dba5977069306e282accddc82e","capture":{"method":"firecrawl"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"dlr-petition-arb","provenance":{"provenance_id":"prov-2952b15a73b647e8f6f1909246540043a6642119eab2b8ddd292d8b989159e6e","source":{"url":"https://www.mass.gov/how-to/file-a-petition-for-arbitration","publisher":"Massachusetts Department of Labor Relations (mass.gov)","title":"File a petition for arbitration","document_date":null},"retrieved_at":"2026-10-12T07:09:21Z","content_sha256":"294a46c168513d79477f780146b893eced4d59a1b1aea5b0b0e6e8a21c27835a","capture":{"method":"firecrawl"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"dlr-overview","provenance":{"provenance_id":"prov-fe5f61dd7efae0ca8e4dc592e00f979fd4a5dba14ea2a585ca58e53bfd36d7e6","source":{"url":"https://www.mass.gov/info-details/overview-of-the-department-of-labor-relations","publisher":"Massachusetts Office of the State Auditor (mass.gov)","title":"Audit of the Department of Labor Relations: overview of the Department of Labor Relations","document_date":null},"retrieved_at":"2026-10-12T07:08:58Z","content_sha256":"e70c1467eda23a7d338698577fc3b5005d7b2ec4318c6b29ede254be9e6d1e8e","capture":{"method":"firecrawl"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"c49170ad-f151-58f4-a4d9-36b1687d0b80","payload":{"kind":"mini_lesson","locale":"es","locale_state":"reviewed","title":"¿Qué es el Departamento de Relaciones Laborales (DLR)?","body":"El Departamento de Relaciones Laborales (Department of Labor Relations, DLR) es la agencia del estado de Massachusetts para las relaciones laborales. Se creó en 2007 al unir la antigua Comisión de Relaciones Laborales y la Junta de Conciliación y Arbitraje, y lo dirige un director nombrado por el gobernador. Según la ley estatal, incluye una oficina de resolución de disputas, un consejo asesor, la Junta de Relaciones Laborales del Estado (CERB) y el Comité Conjunto Laboral-Gerencial (JLMC) para policías y bomberos. Según un informe de la Auditoría del Estado, la mayor parte de su trabajo es decidir cargos por práctica prohibida según la ley c. 150E para empleados públicos y la ley c. 150A para algunos empleadores privados. También organiza elecciones, mediación, determinación de hechos (fact-finding) y arbitraje de quejas. Tiene oficinas en Boston, Springfield y Worcester.","attribution":"","source":"Massachusetts Department of Labor Relations (mass.gov), Public sector unfair labor practice charge, consultada el 12 oct 2026 (https://www.mass.gov/how-to/public-sector-unfair-labor-practice-charge); Massachusetts General Court (malegislature.gov), M.G.L. c. 23, section 9O (Department of Labor Relations), consultada el 12 oct 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleII/Chapter23/Section9O); Massachusetts Department of Labor Relations (mass.gov), FAQ - Impasse, consultada el 12 oct 2026 (https://www.mass.gov/info-details/faq-impasse); Massachusetts Department of Labor Relations (mass.gov), File a petition for arbitration, consultada el 12 oct 2026 (https://www.mass.gov/how-to/file-a-petition-for-arbitration); Massachusetts Office of the State Auditor (mass.gov), Audit of the Department of Labor Relations: overview of the Department of Labor Relations, consultada el 12 oct 2026 (https://www.mass.gov/info-details/overview-of-the-department-of-labor-relations)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","the-board"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-what-is-the-dlr","locale":"es","record":{"provenance_id":"prov-aa5aa338ccb913f1ec315b491e6127a6872f4f2dc2f70fa7e0ca099aca171181","source":{"url":"https://app.example.invalid/#faq-what-is-the-dlr","publisher":"Union Ground platform content (authored draft)","title":"What is the Department of Labor Relations (DLR)?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"dd2a95e388dcf190f928321d6a9a9750b0e894df98a720079d9e5f89201b34f9","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-8d886c64c852c30ba3c7840a80cd711d7fc31ef373b36ab5b1511b79f411d254","prov-4c68364cae54382c7da82b83ee34b292e8897e3320c64fe83bedfcb45f61193a","prov-e35a27fdde2fe7d3a13b665cb6fbd0387053211e82ef5dbc61cd7dd15e151778","prov-2952b15a7