cument_date":null},"retrieved_at":"2026-10-12T07:09:00Z","content_sha256":"0ae5e26e68981f3079548c6c8dffa051821f38ae1cd860fa9f8008c7977599ad","capture":{"method":"firecrawl"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"ma-150e-s11","provenance":{"provenance_id":"prov-d4990f7ba5c14c5bdad936818f6f8ca9730e5ee9d6e76caaf67c03a039b2ae7f","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section11","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 11","document_date":null},"retrieved_at":"2026-10-12T07:04:46Z","content_sha256":"6ea055696317c50f44dc97d7259cefd302236184f44d5ac9d53fbdc50ac7436b","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"ebad531d-f87e-5353-aa7e-803004bc0a1c","payload":{"kind":"mini_lesson","locale":"es","locale_state":"reviewed","title":"¿Qué es la Junta de Relaciones Laborales del Estado (CERB)?","body":"La Junta de Relaciones Laborales del Estado (Commonwealth Employment Relations Board, CERB) es la junta de apelaciones de tres miembros dentro del Departamento de Relaciones Laborales de Massachusetts (DLR). Tiene un presidente de tiempo completo y dos miembros que trabajan por día, nombrados por el gobernador de una lista que envía el consejo asesor del DLR, por períodos de cinco años, y no más de dos pueden ser del mismo partido político. La CERB decide apelaciones de cargos por práctica prohibida desestimados y de decisiones de los oficiales de audiencia, y en algunos casos también decide las unidades de negociación apropiadas. La orden de un oficial de audiencia queda firme salvo que una parte pida a la CERB que la revise dentro de 10 días. Una orden final de la CERB se puede apelar ante el Tribunal de Apelaciones (Appeals Court) dentro de 30 días.","attribution":"","source":"Massachusetts General Court (malegislature.gov), M.G.L. c. 23, section 9R (Commonwealth Employment Relations Board), consultada el 12 oct 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleII/Chapter23/Section9R); Massachusetts Department of Labor Relations (mass.gov), FAQ - General Information, consultada el 12 oct 2026 (https://www.mass.gov/info-details/faq-general-information); Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 11, consultada el 12 oct 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section11)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","the-board"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-what-is-the-cerb","locale":"es","record":{"provenance_id":"prov-c72283a4221f1c316c09414878de45118f3f230f54646a3dcfd2d755aa616a40","source":{"url":"https://app.example.invalid/#faq-what-is-the-cerb","publisher":"U