w":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"mtcll-unions-law","provenance":{"provenance_id":"prov-aff405b89ac74f989f8502acd0a86d06d0174a84cc5f71d7d251720ce8097e3b","source":{"url":"https://www.mass.gov/info-details/massachusetts-law-about-unions-and-collective-bargaining","publisher":"Massachusetts Trial Court Law Libraries (mass.gov)","title":"Massachusetts law about unions and collective bargaining","document_date":null},"retrieved_at":"2026-10-12T07:09:33Z","content_sha256":"964eca777eeee703cefc665647604a1a46b86197df980c18a8735c2b8ad330b3","capture":{"method":"firecrawl"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"usc-29-152","provenance":{"provenance_id":"prov-12171ec99baffa229634d78d17382025affed91de92a3f43a6893ea0faa9e051","source":{"url":"https://www.law.cornell.edu/uscode/text/29/152","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"29 U.S. Code 152 - Definitions (NLRA)","document_date":null},"retrieved_at":"2026-10-12T07:05:52Z","content_sha256":"a758f59a71eb51c948fd457c2ce22c23b0603e0538f8da597ca4b6864fdfe1c7","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"ma-150e-s1","provenance":{"provenance_id":"prov-946c243f5c2e016d2c7cca739060f56da00c7fdffa96b123a14c06623d3d9461","source":{"url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section1","publisher":"Massachusetts General Court (malegislature.gov)","title":"M.G.L. c. 150E, section 1","document_date":null},"retrieved_at":"2026-10-12T07:04:30Z","content_sha256":"f627eeb678daa6ec888fde9e8a968fbbbe17103a17d0ebfed7741f3453a9247c","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"nlrb-jurisdiction","provenance":{"provenance_id":"prov-f6747d339b89e2598ef558abac8732de8d10f7bcb8b99b2b1adab7c8531cbf4d","source":{"url":"https://www.nlrb.gov/about-nlrb/rights-we-protect/the-law/jurisdictional-standards","publisher":"National Labor Relations Board (nlrb.gov)","title":"Jurisdictional Standards","document_date":null},"retrieved_at":"2026-10-12T07:05:45Z","content_sha256":"925e652ec5e92aba1cf7b762886981c2d3f73006a36c3b564555e3989216b7a5","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"be5d66c2-f28f-5366-a042-9ef7fb5bb6b4","payload":{"kind":"mini_lesson","locale":"en","locale_state":"reviewed","title":"What rights do I have inside my union?","body":"If your union is covered by the federal Labor-Management Reporting and Disclosure Act (LMRDA), its \"bill of rights\" gives every member equal rights to nominate candidates, vote in elections, attend membership meetings, and take part in discussion and voting, under reasonable rules. Members may meet freely and express their views. Except for nonpayment of dues, a member may not be fined, suspended or expelled without written specific charges, time to prepare a defense, and a full and fair hearing. The LMRDA may not cover a union made up only of state or local government employees; then look to your union's constitution and bylaws for internal rules, and the DLR generally does not step into internal union affairs.","attribution":"","source":"Massachusetts Department of Labor Relations (mass.gov), F. Prohibited Practices, retrieved Oct 12, 2026 (https://www.mass.gov/info-details/f-prohibited-practices); Legal Information Institute, Cornell Law School (law.cornell.edu), 29 U.S. Code 402 - Definitions (LMRDA), retrieved Oct 12, 2026 (https://www.law.cornell.edu/uscode/text/29/402); Legal Information Institute, Cornell Law School (law.cornell.edu), 29 U.S. Code 411 - Bill of rights; constitution and bylaws of labor organizations, retrieved Oct 12, 2026 (https://www.law.cornell.edu/uscode/text/29/411)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","union-democracy"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-what-rights-do-i-have-inside-my-union","locale":"en","record":{"provenance_id":"prov-8fb6d58173b1f9f6a53f0b1a1cf20e9bc47fdaf0fd18d