exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"usc-29-402","provenance":{"provenance_id":"prov-30e45a7bc7e1b4b3b3cba47cc0bcd2be7f99e80d204c2ea66b47b674a1a1af5e","source":{"url":"https://www.law.cornell.edu/uscode/text/29/402","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"29 U.S. Code 402 - Definitions (LMRDA)","document_date":null},"retrieved_at":"2026-10-12T07:05:56Z","content_sha256":"5cbebb792d0505fb1a72f89392db71d1584fd829b93af2e2905a03f0eb5c1b47","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}},{"source_key":"usc-29-411","provenance":{"provenance_id":"prov-1b9c459692a115193a6b908ee3697b0688a17441c3091f34b1518e4be7ea1d9b","source":{"url":"https://www.law.cornell.edu/uscode/text/29/411","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"29 U.S. Code 411 - Bill of rights; constitution and bylaws of labor organizations","document_date":null},"retrieved_at":"2026-10-12T07:05:58Z","content_sha256":"a4bad78c1e6e0fac5ed46e8a7e927e4aa0244bea5d6bf9029fe03fe66a21cd42","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"105b1ec2-b620-56cf-a0a5-b745867afd36","payload":{"kind":"mini_lesson","locale":"es","locale_state":"reviewed","title":"¿Qué derechos tengo dentro de mi sindicato?","body":"Si su sindicato está cubierto por la ley federal Labor-Management Reporting and Disclosure Act (LMRDA), su \"carta de derechos\" da a cada miembro igualdad de derechos para nominar candidatos, votar en elecciones, asistir a reuniones de miembros y participar en el debate y la votación, según reglas razonables. Los miembros pueden reunirse libremente y expresar sus opiniones. Salvo por falta de pago de cuotas, a un miembro no se le puede multar, suspender ni expulsar sin cargos específicos por escrito, tiempo para preparar su defensa y una audiencia completa y justa. La LMRDA tal vez no cubra a un sindicato formado solo por empleados del gobierno estatal o local; en ese caso, consulte la constitución y los estatutos de su sindicato para conocer las reglas internas, y el DLR generalmente no interviene en los asuntos internos del sindicato.","attribution":"","source":"Massachusetts Department of Labor Relations (mass.gov), F. Prohibited Practices, consultada el 12 oct 2026 (https://www.mass.gov/info-details/f-prohibited-practices); Legal Information Institute, Cornell Law School (law.cornell.edu), 29 U.S. Code 402 - Definitions (LMRDA), consultada el 12 oct 2026 (https://www.law.cornell.edu/uscode/text/29/402); Legal Information Institute, Cornell Law School (law.cornell.edu), 29 U.S. Code 411 - Bill of rights; constitution and bylaws of labor organizations, consultada el 12 oct 2026 (https://www.law.cornell.edu/uscode/text/29/411)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","union-democracy"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-what-rights-do-i-have-inside-my-union","locale":"es","record":{"provenance_id":"prov-8fb6d58173b1f9f6a53f0b1a1cf20e9bc47fdaf0fd18da06eea0578dd236d336","source":{"url":"https://app.example.invalid/#faq-what-rights-do-i-have-inside-my-union","publisher":"Union Ground platform content (authored draft)","title":"What rights do I have inside my union?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"a705bd2f4514b897c20821e5ecbb74215546e6c880f63918ef907a52120288f9","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-ecae6940b308e391c248946ec43aa6ac002944d053d015fb9b902296489b0551","prov-30e45a7bc7e1b4b3b3cba47cc0bcd2be7f99e80d204c2ea66b47b674a1a1af5e","prov-1b9c459692a115193a6b908ee3697b0688a17441c3091f34b1518e4be7ea1d9b"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"dlr-f-prohibited","provenance":{"provenance_id":"prov-ecae6940b308e391c