10-12T07:05:58Z","content_sha256":"a4bad78c1e6e0fac5ed46e8a7e927e4aa0244bea5d6bf9029fe03fe66a21cd42","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"8058da5a-7bf3-5f66-a5fd-afa99870994e","payload":{"kind":"mini_lesson","locale":"en","locale_state":"reviewed","title":"How often are union officers elected?","body":"For unions covered by the federal Labor-Management Reporting and Disclosure Act (LMRDA), a local union must elect its officers at least once every three years by secret ballot among members in good standing. A national or international union must elect officers at least every five years, by secret ballot or at a convention of delegates chosen by secret ballot. Intermediate bodies elect at least every four years. Candidates have rights too, such as having campaign literature distributed at their own expense. For a union the LMRDA may not cover, check its constitution and bylaws for election rules. Ask your union office for its election rules and the next election date.","attribution":"","source":"Legal Information Institute, Cornell Law School (law.cornell.edu), 29 U.S. Code 481 - Terms of office; election procedures, retrieved Oct 12, 2026 (https://www.law.cornell.edu/uscode/text/29/481)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","union-democracy"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-how-often-are-officers-elected","locale":"en","record":{"provenance_id":"prov-de221f1624bc3c669308ca00ad7310c09e6d96a1418bc2ce3ceda20ccb3666ea","source":{"url":"https://app.example.invalid/#faq-how-often-are-officers-elected","publisher":"Union Ground platform content (authored draft)","title":"How often are union officers elected?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"97b41bee6dfa5df1ef9ff431c26d2e9848d76e7c9f7acde73ba9d357e64dfdd4","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-0cc63c4f20e8867dafb55fd138b20b48f399f3d051500368a7574ea3d999a454"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"usc-29-481","provenance":{"provenance_id":"prov-0cc63c4f20e8867dafb55fd138b20b48f399f3d051500368a7574ea3d999a454","source":{"url":"https://www.law.cornell.edu/uscode/text/29/481","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"29 U.S. Code 481 - Terms of office; election procedures","document_date":null},"retrieved_at":"2026-10-12T07:06:00Z","content_sha256":"9800cdd55885d01e3b0f62d9e41452ebb4d1fb8149ea6f97142cd7afc987690c","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"86e5e2d0-b240-5174-a245-f830908a356e","payload":{"kind":"mini_lesson","locale":"es","locale_state":"reviewed","title":"¿Cada cuánto se elige a los funcionarios del sindicato?","body":"En los sindicatos cubiertos por la ley federal Labor-Management Reporting and Disclosure Act (LMRDA), un sindicato local debe elegir a sus funcionarios al menos una vez cada tres años por votación secreta entre los miembros en regla. Un sindicato nacional o internacional debe elegirlos al menos cada cinco años, por votación secreta o en una convención de delegados elegidos por votación secreta. Los organismos intermedios eligen al menos cada cuatro años. Los candidatos también tienen derechos, como pedir que se distribuya su material de campaña a su propio costo. En un sindicato que la LMRDA tal vez no cubra, revise su constitución y sus estatutos para conocer las reglas de elección. Pida a la oficina de su sindicato sus reglas de elección y la fecha de la próxima elección.","attribution":"","source":"Legal Information Institute, Cornell Law School (law.cornell.edu), 29 U.S. Code 481 - Terms of office; election procedures, consultada el 12 oct 2026 (https://www.law.cornell.edu/uscode/text/29/481)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","union-democracy"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-how-often-are-officers-elected","locale":"es","record":{"provenance_id":"prov-de221f1624bc3c669308ca00ad7310c09e6d96a1418bc2ce3ceda20ccb3666ea","source":{"url":"https://app.example.invalid/#faq-how-often-are-officers-elected","publisher":"Union Ground platform content (authored draft)","title":"How often are union officers elected?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"97b41bee6dfa5df1ef9ff431c26d2e9848d76e7c9f7acde73ba9d357e64dfdd4","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation, en+es; quotes checked by quotation validation","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":["prov-0cc63c4f20e8867dafb55fd138b20b48f399f3d051500368a7574ea3d999a454"],"review":{"status":"reviewed","reviewed_at":"2026-10-12T07:41:37Z","reviewer_role":"content reviewer","note":"Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication."},"reuse":{"basis":"owner-authored","note":"Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only."}},"source_records":[{"source_key":"usc-29-481","provenance":{"provenance_id":"prov-0cc63c4f20e8867dafb55fd138b20b48f399f3d051500368a7574ea3d999a454","source":{"url":"https://www.law.cornell.edu/uscode/text/29/481","publisher":"Legal Information Institute, Cornell Law School (law.cornell.edu)","title":"29 U.S. Code 481 - Terms of office; election procedures","document_date":null},"retrieved_at":"2026-10-12T07:06:00Z","content_sha256":"9800cdd55885d01e3b0f62d9e41452ebb4d1fb8149ea6f97142cd7afc987690c","capture":{"method":"http-get"},"extraction":{"method":"verbatim","extractor":"public source capture text view","quote_binding":"exact-substring"},"as_of":"2026-10-12","derived_from":[],"review":{"status":"unreviewed","reviewed_at":null,"reviewer_role":"content reviewer","note":""},"reuse":{"basis":"public-record","note":"Cited and paraphrased; not republished in full."}}}]}},{"id":"a04daf3e-bfde-5b83-abd6-ffd526057f98","payload":{"kind":"mini_lesson","locale":"en","locale_state":"reviewed","title":"How do I get a copy of my contract or my union's bylaws?","body":"Start by asking your steward or union office. For unions covered by the federal Labor-Management Reporting and Disclosure Act (LMRDA), the local union's secretary must send a copy of the contract to any employee whose rights it directly affects who asks for one, and covered unions must file their constitution and bylaws with the U.S. Department of Labor, where you can find them in the OLMS Online Public Disclosure Room. In Massachusetts public employment, the employer must file each signed contract with the state and with the legislature's ways and means committees. You can also send a public records request to the Department of Labor Relations (DLR).","attribution":"","source":"Massachusetts Department of Labor Relations (mass.gov), Public sector unfair labor practice charge, retrieved Oct 12, 2026 (https://www.mass.gov/how-to/public-sector-unfair-labor-practice-charge); Legal Information Institute, Cornell Law School (law.cornell.edu), 29 U.S. Code 414 - Right to copies of collective bargaining agreements, retrieved Oct 12, 2026 (https://www.law.cornell.edu/uscode/text/29/414); U.S. Department of Labor, Office of Labor-Management Standards (dol.gov), OLMS Online Public Disclosure Room, retrieved Oct 12, 2026 (https://www.dol.gov/agencies/olms/public-disclosure-room); Legal Information Institute, Cornell Law School (law.cornell.edu), 29 U.S. Code 431 - Report of labor organizations, retrieved Oct 12, 2026 (https://www.law.cornell.edu/uscode/text/29/431); Massachusetts General Court (malegislature.gov), M.G.L. c. 150E, section 7, retrieved Oct 12, 2026 (https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter150E/Section7)","rights_note":"owner-authored: Original plain-language text drafted for the platform; statutes, regulations, agency pages and court opinions are cited and paraphrased, short quotations only.","review_note":"source review, 2026-10-12T07:41:37Z: Fresh-context verification pass: every claim read against its verbatim source quotes in context, Spanish checked against English, jurisdiction and affiliation guardrails checked. Not yet reviewed by the platform editor; editor review is required before publication.","bullets":[],"direction":"","topics":["faq","union-democracy"],"audience":"all","tone":"","learning_outcome":"","factual_claims":true,"priority":0,"is_default":false},"provenance":{"content_path":"content/explainer-content/faq.json","unit_id":"faq-how-do-i-get-my-contract-or-bylaws","locale":"en","record":{"provenance_id":"prov-05f0148c12797ca8f0a724761f55766cb37dd667b10791ddd1864a1635e51b1b","source":{"url":"https://app.example.invalid/#faq-how-do-i-get-my-contract-or-bylaws","publisher":"Union Ground platform content (authored draft)","title":"How do I get a copy of my contract or my union's bylaws?","document_date":"2026-10-12"},"retrieved_at":"2026-10-12T07:42:08Z","content_sha256":"d32da7c564dfd5e4876124c106a01740eaf2e0649016105ea9908879859a79fa","capture":{"method":"authored"},"extraction":{"method":"model","extractor":"bilingual draft generation,